@Composable
fun JsAutoResizeText(
    text: String,
    maxTextSize: Int,
    minTextSize: Int = 0,
    modifier: Modifier = Modifier,
    fontWeight: FontWeight = FontWeight.Light,
    color: Color = JsMainTheme.colors.text_color_default,
    textAlign: TextAlign = TextAlign.Start,
    overflow: TextOverflow = TextOverflow.Clip,
    textDecoration: TextDecorationLine = TextDecorationLine.None,
    maxLines: Int? = null,
) {
    val remSize = maxTextSize / 16.0 // 1 rem = 16px
    val minRemSize =
        if (minTextSize > 0) minTextSize / 16.0 else if (isMobileDevice) remSize * 0.9 else remSize * 0.7
    val minAbsolute = if (isMobileDevice) 0.6 else 0.75
    val min = maxOf(minAbsolute, minRemSize)
    val max = if (isMobileDevice) remSize * 1.1 else remSize * 1.0
    Span(
        attrs = modifier.textDecorationLine(textDecoration)
            .styleModifier {
                fontSize(clamp(min.cssRem, 2.5.vw, max.cssRem))
                color(color)
                fontWeight(fontWeight)
                userSelect(UserSelect.None)
                if (maxLines != null) {
                    display(DisplayStyle("-webkit-box"))
                    property("-webkit-line-clamp", maxLines.toString())
                    property("-webkit-box-orient", "vertical")
                    textOverflow(overflow)
                }
                overflow(Overflow.Hidden)
                whiteSpace("pre-wrap")
                textAlign(textAlign)
            }
            .toAttrs()
    ) {
        Text(text)
    }
}

@Composable
fun JsTextView(
    text: String,
    textSize: Int,
    modifier: Modifier = Modifier,
    fontWeight: FontWeight = FontWeight.Normal,
    textColor: Color = JsMainTheme.colors.text_color_default,
    textAlign: TextAlign = TextAlign.Start,
    textDecoration: TextDecorationLine = TextDecorationLine.None,
    maxLines: Int? = null,
) {
    val remSize = textSize / 16.0 // 1 rem = 16px
    val minAbsolute = if (isMobileDevice) 0.6 else 0.75
    val minRemSize = if (isMobileDevice) remSize * 0.9 else remSize * 0.7
    val min = maxOf(minAbsolute, minRemSize)
    val max = if (isMobileDevice) remSize * 1.1 else remSize * 1.0
    Span(
        attrs = modifier.textDecorationLine(textDecoration)
            .styleModifier {
                fontSize(clamp(min.cssRem, 2.5.vw, max.cssRem))
                color(textColor)
                fontWeight(fontWeight)
