class Database : IDatabase {

    override fun clearDatabase() {
        CoroutineScope(Dispatchers.Default).launch {
            IndexedDbStorage.deleteDatabase()
        }
    }

    override fun saveAccounts(accounts: List<Account>?) {
        CoroutineScope(Dispatchers.Default).launch {
            IndexedDbStorage.saveAllItems(StoreName.accounts, accounts)
        }
    }

    override suspend fun saveAccount(account: Account?) {
        IndexedDbStorage.saveItem(StoreName.accounts, account)
    }

    override suspend fun saveMyAccount(
        account: Account?,
        login: String
    ) {
        if (account == null) return
        CoroutineScope(Dispatchers.Default).launch {
            val dbAccount = getAccountByLogin(login)
            val result = MergeObjectsUtils.mergeObjects(account, dbAccount)
            result?.let { IndexedDbStorage.saveItem(StoreName.accounts, it) }
        }
    }

    override fun saveAccountWithoutMerge(account: Account?) {
        CoroutineScope(Dispatchers.Default).launch {
            IndexedDbStorage.saveItem(StoreName.accounts, account)
        }
    }

    override suspend fun getAccountById(id: String): Account? =
        IndexedDbStorage.getItemById<Account?>(StoreName.accounts, id)

    override suspend fun getAccountByLogin(login: String): Account? =
        IndexedDbStorage.getItemByLogin(StoreName.accounts, login)


    override fun getAccountFilter(id: String): AccountFilter? {
        val stringObject = LocalStorageManager.getString("account_filter")
        return JsonObjectConverter.stringToObject(stringObject)
    }

    override fun saveAccountFilter(accountFilter: AccountFilter?) {
