@Composable
fun InitTheme(
    withBackground: Boolean = true,
    withNavBarPadding: Boolean = false,
    content: @Composable (Modifier) -> Unit
) {
    MainAppTheme {
        Column(Modifier.fillMaxSize()) {
            if (withBackground) Surface(
                modifier = Modifier.fillMaxWidth().weight(1f),
                color = MainTheme.colors.main_color_background
            ) { content.invoke(Modifier.fillMaxSize()) }
            else content.invoke(Modifier.fillMaxWidth().weight(1f))

            if (withNavBarPadding) NavigationBarPadding()
        }
    }
}

@Composable
fun PageContainer(
    withBackground: Boolean = true, withNavBarPadding: Boolean = false,
    content: @Composable (BoxScope.() -> Unit)
) {
    InitTheme(
        withBackground,
        withNavBarPadding
    ) { modifier -> Box(modifier) { content.invoke(this) } }
}

@Composable
fun PageContainerColumn(
    withBackground: Boolean = true,
    withNavBarPadding: Boolean = true,
    scrollable: Boolean = false,
    content: @Composable (ColumnScope.() -> Unit)
) {
    val modifier = if (scrollable) Modifier.verticalScroll(rememberScrollState()) else Modifier
    InitTheme(withBackground, withNavBarPadding) { Column(modifier = modifier) { content.invoke(this) } }
}

