@Composable
fun ShapeButton(
    buttonTitle: String,
    showProgress: Boolean = false,
    modifier: Modifier = Modifier,
    titleModifier: Modifier = Modifier,
    shape: RoundedCornerShape = CircleShape,
    buttonColor: Color = MainTheme.colors.app_main_color,
    disabledButtonColor: Color = MaterialTheme.colors.onSurface.copy(alpha = 0.12f)
        .compositeOver(MaterialTheme.colors.surface),
    textColor: Color = MainTheme.colors.text_color_default,
    textWeight: FontWeight = FontWeight.Medium,
    textSizeMax: TextUnit = 15.sp,
    textSizeMin: TextUnit = 8.sp,
    textAlign: TextAlign = TextAlign.Justify,
    textMaxLine: Int = 1,
    enabled: Boolean = true,
    horizontalPadding: Dp = 16.dp,
    onClick: () -> Unit
) {
    Button(
        onClick = onClick,
        modifier = modifier,
        enabled = enabled,
        shape = shape,
        colors = ButtonDefaults.buttonColors(
            backgroundColor = buttonColor, disabledBackgroundColor = disabledButtonColor
        ),
        contentPadding = PaddingValues(vertical = 8.dp, horizontal = horizontalPadding)
    ) {
        if (showProgress) {
            LoadingState()
        } else {
            AutoResizeText(
                modifier = titleModifier,
                text = buttonTitle,
                fontSizeRange = FontSizeRange(textSizeMax, textSizeMin),
                color = textColor,
                fontWeight = textWeight,
                textAlign = textAlign,
                maxLines = textMaxLine,
                style = TextStyle.Default,
                rememberKey = buttonTitle
            )
        }
    }
}

