@Composable
fun MainButtonCustom(
    text: String,
    colors: List<Color>,
    arrowIsVisible: Boolean = false,
    alpha: Float = 1f,
    widthBtn: Dp = 0.dp,
    onClick: () -> Unit
) {
    val screenWidth = getScreenSizeInfo().widthDp
    val buttonWidth = if (widthBtn == 0.dp) screenWidth else widthBtn
    MainAppTheme {
        Box(
            modifier = Modifier
                .width(buttonWidth)
                .alpha(alpha)
                .clip(RoundedCornerShape(if (screenWidth - buttonWidth > 0.dp) 8.dp else 0.dp))
                .height(50.dp)
                .clickable { onClick() }, contentAlignment = Alignment.Center
        ) {
            if (colors.size <= 1) {
                val backgroundColor = colors.firstOrNull() ?: MainTheme.colors.app_main_color
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(backgroundColor)
                )
            } else {
                val gradient = Brush.linearGradient(
                    colors,
                    start = Offset(0f, Float.POSITIVE_INFINITY),
                    end = Offset(Float.POSITIVE_INFINITY, 0f)
                )
                Box(
                    modifier = Modifier
                        .fillMaxSize()
                        .background(gradient)
                )
            }

            Text(
                text = text,
                color = Color.White,
                fontSize = 16.sp,
                fontWeight = FontWeight.Medium,
            )
            if (arrowIsVisible) {
                Box(
                    modifier = Modifier.fillMaxSize(), contentAlignment = Alignment.CenterEnd
                ) {
                    CustomImageView(
                        Res.drawable.ic_arrow_right,
                        modifier = Modifier
                            .fillMaxHeight()
                            .padding(end = 48.dp - ((screenWidth - buttonWidth) / 2))
                    )
                }
            }
        }
    }
}

@Composable
fun ButtonPulse(
    buttonText: String,
    colors: List<Color>,
    arrowIsVisible: Boolean,
    durationMillis: Int = 1000,
    maxPulseHeight: Float = 70f,
    minPulseHeight: Float = 50f,
    withHorizontalPadding: Boolean = false,
    buttonClick: () -> Unit
) {
    val infiniteTransition = rememberInfiniteTransition(label = "")
    val height = infiniteTransition.animateFloat(
        initialValue = minPulseHeight,
        targetValue = maxPulseHeight,
        animationSpec = infiniteRepeatable(
            animation = tween(durationMillis, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        ),
        label = ""
    )
    val screenWidth = getScreenSizeInfo().widthDp
    val minWidth = screenWidth - if (withHorizontalPadding) 40.dp else 0.dp
    val width = if (!withHorizontalPadding) screenWidth else infiniteTransition.animateFloat(
        initialValue = minWidth.value,
        targetValue = screenWidth.value,
        animationSpec = infiniteRepeatable(
            animation = tween(durationMillis, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        ),
        label = ""
    ).value.dp

    val alpha = infiniteTransition.animateFloat(
        initialValue = 1f, targetValue = 0f, animationSpec = infiniteRepeatable(
            animation = tween(durationMillis, easing = LinearEasing),
            repeatMode = RepeatMode.Restart
        ), label = ""
    )
    Box(
        contentAlignment = Alignment.Center,
        modifier = Modifier
            .fillMaxWidth()
            .height(maxPulseHeight.dp)
    ) {

        if (colors.size <= 1) {
            val backgroundColor = colors.firstOrNull() ?: MainTheme.colors.app_main_color
            Box(
                modifier = Modifier
                    .width(width)
                    .height(height.value.dp)
                    .clip(RoundedCornerShape(if (withHorizontalPadding) 8.dp else 0.dp))
                    .alpha(alpha.value)
                    .background(backgroundColor)
            )
        } else {
            val gradient = Brush.linearGradient(
                colors,
                start = Offset(0f, Float.POSITIVE_INFINITY),
                end = Offset(Float.POSITIVE_INFINITY, 0f)
            )
            Box(
                modifier = Modifier
                    .width(width)
                    .height(height.value.dp)
                    .clip(RoundedCornerShape(if (withHorizontalPadding) 8.dp else 0.dp))
                    .alpha(alpha.value)
                    .background(gradient)
            )
        }

        MainButtonCustom(
            text = buttonText, colors = colors, arrowIsVisible = arrowIsVisible, widthBtn = minWidth
        ) { buttonClick.invoke() }
    }
}

@Composable
fun ShapeGradientButton(
    buttonTitle: String,
    showProgress: Boolean = false,
    modifier: Modifier = Modifier,
    titleModifier: Modifier = Modifier,
    shape: RoundedCornerShape = CircleShape,
    startColor: Color = MainTheme.colors.gradient_main_button_start,
    endColor: Color = MainTheme.colors.gradient_main_button_end,
    textColor: Color = MainTheme.colors.text_color_default,
    textWeight: FontWeight = FontWeight.Medium,
    textSizeMax: TextUnit = 15.sp,
    textSizeMin: TextUnit = 8.sp,
    textAlign: TextAlign = TextAlign.Justify,
    textMaxLine: Int = 1,
    enabled: Boolean = true,
    onClick: () -> Unit
) {
    val colorList = listOf(startColor, endColor)
    val gradient = Brush.linearGradient(
        colorList, start = Offset(0f, Float.POSITIVE_INFINITY),
        end = Offset(Float.POSITIVE_INFINITY, 0f)
    )
    Box(
        modifier = modifier
            .height(50.dp)
            .fillMaxWidth(0.8f)
            .clip(shape)
            .background(brush = gradient, shape = shape)
            .clickable {
                onClick.invoke()
            }, contentAlignment = Alignment.Center
    ) {
        if (showProgress) {
            LoadingState()
        } else {
            AutoResizeText(
                modifier = titleModifier.padding(horizontal = 8.dp),
                text = buttonTitle,
                fontSizeRange = FontSizeRange(textSizeMax, textSizeMin),
                color = textColor,
                fontWeight = textWeight,
                textAlign = textAlign,
                maxLines = textMaxLine,
                style = TextStyle.Default,
                rememberKey = buttonTitle
            )
        }
    }
}

