@Composable
fun Dp.dpToPx() = with(LocalDensity.current) { this@dpToPx.toPx() }

@Composable
fun Int.pxToDp() = with(LocalDensity.current) { this@pxToDp.toDp() }


fun Modifier.clickable(
    indication: Indication?,
    enabled: Boolean = true,
    onClick: () -> Unit
) = clickable(MutableInteractionSource(), indication, enabled = enabled, onClick = onClick)

fun Modifier.customShadow(
    elevation: Dp,
    shape: Shape = RectangleShape,
    shapeColor: Color = DefaultShadowColor,
) = this.padding(elevation)
    .shadow(elevation, shape, spotColor = shapeColor)
    .clip(shape)