@Composable
fun StripeByAppleGoogleScreen(
    viewModel: PaywallScreenVM,
    onPurchase: (String, String?) -> Unit,
    onError: (String) -> Unit
) {
    val showCardInput = remember { mutableStateOf(false) }
    val payPalAvailable = remember { mutableStateOf(false) }
    val applePayAvailable = remember { mutableStateOf(false) }
    val googlePayAvailable = remember { mutableStateOf(false) }

    val selectedProductId = viewModel.selectedProductID.value
    val stripeProduct =
        BillingManager.productDetailsList.firstOrNull { it.productId == selectedProductId }
            ?: return

    LaunchedEffect(stripeProduct) {
        try {
            val publicKey =
                "pk_test_51RH1h7PnYFKJZeAUKQGgck4axVz7NaduAcM8wL3vz0W0BWqV1mPqd0DMYNmUQUQIbpyVTylANCqc0IbXHdX9VWhr00dFIIPSiq"
            StripeInterop.initStripe(publicKey)

            // 2. Проверка доступности Google Pay и Apple Pay
            val prAvailability = initStripePaymentRequest(
                amountInCents = (stripeProduct.amount ?: 0).toInt(),
                currency = (stripeProduct.currency ?: "").lowercase(),
                countryCode = "US",
                label = stripeProduct.description ?: "",
            )
            prAvailability?.let {
                applePayAvailable.value = it.applePay
                googlePayAvailable.value = it.googlePay

                // Устанавливаем коллбэки для Payment Request
                StripeInterop.setGooglePayPaymentMethodCallback { paymentMethodId ->
                    console.log("Google Pay Payment Method ID: $paymentMethodId")
                    onPurchase(paymentMethodId, stripeProduct.priceId)
                }
                StripeInterop.setApplePayPaymentMethodCallback { paymentMethodId ->
                    console.log("Apple Pay Payment Method ID: $paymentMethodId")
                    onPurchase(paymentMethodId, stripeProduct.priceId)
                }
                StripeInterop.setupPaymentRequestListeners() // Активируем слушателей
                console.log("Stripe initialization success")
            }
        } catch (e: Throwable) {
            onError("Stripe initialization error: $e")
            console.error("Stripe initialization error: $e")
        }
    }

    JsAnimatedVisibility(
        visible = viewModel.showStripeAppleGoogle.value,
        durationMs = 300,
        modifier = Modifier.fillMaxSize().zIndex(5)
    ) {
        Box(
            Modifier.fillMaxSize()
                .background(JsMainTheme.colors.main_color_black_transparent_50)
                .clickable {
                    viewModel.showStripeAppleGoogle.value = false
                },
            contentAlignment = Alignment.BottomCenter
        ) {
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .borderRadius(
                        topLeft = 24.dp,
                        topRight = 24.dp,
                        bottomRight = 0.dp,
                        bottomLeft = 0.dp
                    )
                    .background(JsMainTheme.colors.box_subscribe_propose_backgraund_gray)
                    .onClick { event -> event.stopPropagation() }
            ) {
                Column(modifier = Modifier.fillMaxWidth().padding(horizontal = 20.dp)) {
                    Spacer(Modifier.height(20.dp))

                    Box(
                        Modifier.fillMaxWidth().height(54.dp)
                            .padding(horizontal = 16.dp, vertical = 12.dp)
                            .clipByCorner()
                            .background(Color.rgb(0x056FDD))
                            .clickable {
                                showCardInput.value = true
                            },
                        contentAlignment = Alignment.Center
                    ) {
                        Row(
                            verticalAlignment = Alignment.CenterVertically,
                            horizontalArrangement = Arrangement.spacedBy(8.dp)
                        ) {
                            JsImageView("ic_stripe_pay_card_web", modifier = Modifier.size(18.dp))

                            JsTextView(
                                text = "Debit / Credit Card",
                                textColor = JsMainTheme.colors.text_color_white,
                                textSize = 14,
                                fontWeight = FontWeight.Bold
                            )
                        }
                    }

                    if (payPalAvailable.value || applePayAvailable.value || googlePayAvailable.value) {
                        Spacer(Modifier.height(16.dp))
                        Box(Modifier.fillMaxWidth(), contentAlignment = Alignment.Center) {
                            Spacer(
                                Modifier.fillMaxWidth().height(1.dp).background(Color.rgb(0xC0C0C0))
                            )

                            JsTextView(
                                text = "OR",
                                modifier = Modifier.padding(horizontal = 32.dp)
                                    .background(JsMainTheme.colors.box_subscribe_propose_backgraund_gray),
                                textColor = JsMainTheme.colors.text_color_white,
                                textSize = 12,
                            )
                        }
                        Spacer(Modifier.height(6.dp))
                    }

                    if (payPalAvailable.value) {
                        Spacer(Modifier.height(10.dp))
                        Box(
                            Modifier.fillMaxWidth().height(54.dp)
                                .padding(horizontal = 16.dp, vertical = 12.dp)
                                .clipByCorner()
                                .background(Color.rgb(0xFFC700)),
                            contentAlignment = Alignment.Center
                        ) {
                            JsImageView(
                                "ic_stripe_pay_paypal_web",
                                modifier = Modifier.fillMaxHeight()
                            )
                        }
                    }


                    if (applePayAvailable.value) {
                        Spacer(Modifier.height(10.dp))
                        Box(
                            Modifier.fillMaxWidth().height(54.dp)
                                .padding(horizontal = 16.dp, vertical = 12.dp)
                                .clipByCorner()
                                .background(Color.rgb(0xFFFFFF))
                                .clickable { StripeInterop.triggerPaymentRequest() },
                            contentAlignment = Alignment.Center
                        ) {
                            JsImageView(
                                "ic_stripe_pay_apple_web",
                                modifier = Modifier.fillMaxHeight()
                            )
                        }
                    }


                    if (googlePayAvailable.value) {
                        Spacer(Modifier.height(10.dp))
                        Box(
                            Modifier.fillMaxWidth().height(54.dp)
                                .padding(horizontal = 16.dp, vertical = 12.dp)
                                .clipByCorner()
                                .background(Color.rgb(0xEEEEEE))
                                .clickable { StripeInterop.triggerPaymentRequest() },
                            contentAlignment = Alignment.Center
                        ) {
                            JsImageView(
                                "ic_stripe_pay_google_web",
                                modifier = Modifier.fillMaxHeight()
                            )
                        }
                    }
                    Spacer(Modifier.height(16.dp))
                }
            }
            if (showCardInput.value) Box(
                Modifier.fillMaxSize()
                    .background(JsMainTheme.colors.main_color_black_transparent_50)
                    .clickable { showCardInput.value = false },
                contentAlignment = Alignment.Center
            ) {
                DisposableEffect(Unit) {
                    setupCardElementAndCallback(WebContainer.PaymentScreen.screenName) { paymentMethodId, errorMessage ->
                        if (paymentMethodId != null) {
                            onPurchase(paymentMethodId, stripeProduct.priceId)
                        } else {
                            viewModel.dialogManager.showMessageDialog(errorMessage ?: "")
                        }
                    }

                    onDispose {
                        StripeInterop.unmountCardElement()
                        document.getElementById(WebContainer.PaymentScreen.screenName)?.remove()
                    }
                }

                Box(
                    Modifier.fillMaxWidth().padding(horizontal = 16.dp)
                        .onClick { event -> event.stopPropagation() }
                ) {
                    Column(
                        Modifier.fillMaxWidth()
                            .padding(start = 16.dp, end = 12.dp, top = 24.dp, bottom = 16.dp)
                            .clipByCorner(24)
                            .background(JsMainTheme.colors.box_subscribe_propose_backgraund_gray)
                    ) {
                        Div(
                            attrs = Modifier.id(WebContainer.PaymentScreen.screenName)
                                .fillMaxWidth()
                                .padding(start = 8.dp)
                                .height(50.px)
                                .toAttrs()
                        ) {

                        }

                        Box(
                            Modifier.fillMaxWidth().height(54.dp).padding(start = 8.dp, end = 12.dp)
                        ) {
                            Box(
                                Modifier.fillMaxWidth().height(54.dp)
                                    .padding(horizontal = 16.dp, vertical = 12.dp)
                                    .clipByCorner()
                                    .background(Color.rgb(0x056FDD))
                                    .clickable {
                                        StripeInterop.triggerCardPaymentMethodCreation()
                                    },
                                contentAlignment = Alignment.Center
                            ) {
                                JsTextView(
                                    text = "Pay",
                                    textColor = JsMainTheme.colors.text_color_white,
                                    textSize = 14,
                                    fontWeight = FontWeight.Bold
                                )
                            }
                        }
                    }
                }
            }
        }
    }
}

object StripeManager {

    fun setupCardElementAndCallback(
        elementId: String,
        onPaymentMethodCallback: (String?, String?) -> Unit
    ) {
        StripeInterop.setupCardElement(elementId, onPaymentMethodCallback)
    }

    suspend fun initStripePaymentRequest(
        amountInCents: Int,
        currency: String,
        countryCode: String,
        label: String
    ): PaymentRequestAvailability? {
        return try {
            StripeInterop.initializePaymentRequest(amountInCents, currency, countryCode, label)
                .await()
        } catch (e: dynamic) {
            console.error("Error initializing payment request: $e")
            null
        }
    }
}