@Composable
fun JsSubscriptionButtonHorizontalContent(
    periodTitle: String,
    textPrices: TextPricesAndPercent,
    isReview: Boolean,
    isWeekFormat: Boolean,
) {
    val price = textPrices.textPriceDiscountPeriod.ifEmpty { textPrices.textPricePeriod }

    Box(
        modifier = Modifier.fillMaxSize(),
        contentAlignment = Alignment.Center
    ) {
        Row(
            modifier = Modifier
                .fillMaxSize()
                .padding(
                    start = 24.dp,
                    end = if (isReview) 8.dp else 24.dp,
                    top = 8.dp,
                    bottom = 8.dp
                ),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {

            Column(
                modifier = Modifier.width((if (isReview) 0.6f else 0.4f).toPercent())
            ) {
                JsAutoResizeText(
                    text = periodTitle.uppercase(),
                    maxTextSize = if (isReview) 10 else 14,
                    fontWeight = FontWeight.Medium
                )
                if (isReview) {
                    JsAutoResizeText(
                        text = price.uppercase(),
                        maxTextSize = 14,
                        fontWeight = FontWeight.Medium
                    )
                }
            }

            Box(
                modifier = Modifier
                    .height(if (isReview) 36.dp else 30.dp)
                    .width((if (isReview) 0.4f else 0.6f).toPercent())
                    .clipByCorner()
                    .background(JsMainTheme.colors.text_color_default.copy(alpha = 0.2f)),
                contentAlignment = Alignment.Center
            ) {
                PricePerWeekString(textPrices.textDefaultPriceWeek, isReview, isWeekFormat)
            }
        }
    }
}

@Composable
private fun PricePerWeekString(
    price: String, isReview: Boolean, isWeekFormat: Boolean
) {
    val priceFontSize = remember { mutableStateOf(if (isReview) 14 else 22) }
    val perWeekFontSize = remember { mutableStateOf(if (isReview) 14 else 12) }
    val perWeek = stringResource(
        if (isWeekFormat) {
            /*if (isReview) Res.string.subscribe_settings_per_week_text
            else*/ Res.string.subscribe_settings_weekly_text
        } else {
            /*if (isReview) Res.string.subscribe_settings_per_month_text
            else*/ Res.string.subscribe_settings_month_text
        }
    )

    JsAnnotatedStringsText(
        annotatedStrings = priceAnnotationString(
            price,
            priceFontSize.value,
            perWeek = perWeek,
            perWeekFontSize.value,
            isReview
        ),
        textSize = perWeekFontSize.value,
        textColor = JsMainTheme.colors.text_color_default,
        modifier = Modifier.padding(horizontal = 16.dp),
        textAlign = TextAlign.Center
    )

}

@Composable
private fun priceAnnotationString(
    price: String,
    priceFontSize: Int,
    perWeek: String,
    perWeekFontSize: Int,
    isReview: Boolean,
): List<AnnotatedString> {
    val annotatedString = mutableListOf<AnnotatedString>()
    annotatedString.add(
        AnnotatedString(
            price.uppercase(),
            Modifier.styleModifier { fontWeight(FontWeight.Bold) },
            textSize = priceFontSize
        )
    )

    annotatedString.add(
        AnnotatedString("  ", null)
    )

    annotatedString.add(
        AnnotatedString(
            if (isReview) perWeek.lowercase() else perWeek.lowercase(),
            Modifier.styleModifier { fontWeight(FontWeight.Bold) },
            textSize = perWeekFontSize
        )
    )
    return annotatedString
}

@Composable
private fun PricePerWeek(price: String, isReview: Boolean, isWeekFormat: Boolean) {
    val perWeek = stringResource(
        if (isWeekFormat) {
            /*if (isReview) Res.string.subscribe_settings_per_week_text
            else */Res.string.subscribe_settings_weekly_text
        } else {
            /*if (isReview) Res.string.subscribe_settings_per_month_text
            else */Res.string.subscribe_settings_month_text
        }
    )
    Row(
        modifier = Modifier.padding(horizontal = 16.dp),
        verticalAlignment = Alignment.CenterVertically,
        horizontalArrangement = Arrangement.Center
    ) {
        JsAutoResizeText(
            modifier = Modifier.weight(1.1f),
            text = price.uppercase(),
            maxTextSize = if (isReview) 14 else 22,
            minTextSize = if (isReview) 10 else 12,
            color = JsMainTheme.colors.text_color_default,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center,
            maxLines = 1
        )

        JsAutoResizeText(
            modifier = Modifier.weight(0.9f),
            text = if (isReview) perWeek else " ${perWeek.lowercase()}",
            maxTextSize = if (isReview) 14 else 12,
            minTextSize = if (isReview) 10 else 8,
            color = JsMainTheme.colors.text_color_default,
            fontWeight = FontWeight.Bold,
            textAlign = TextAlign.Center,
            maxLines = 1
        )
    }
}