//@Entity
@kotlinx.serialization.Serializable
data class AccountCompatibilities(
    @SerialName("goals") var goals: Double = 0.0,
    @SerialName("lifestyle") var lifestyle: Double = 0.0,
    @SerialName("habits") var habits: Double = 0.0,
    @SerialName("mindset") var mindset: Double = 0.0,
    @SerialName("sex") var sexual: Double = 0.0,
    @SerialName("libido") var libido: Double = 0.0,
    @SerialName("extreme") var extreme: Double = 0.0
) {
    fun calculateAverage(): Int {
        val average =
            /*if (AppVariant.isParadiz()) (goals + mindset + sexual + libido + extreme) / 5.0
            else*/ (goals + lifestyle + mindset + sexual + habits) / 5.0
        return roundValue(average)
    }

    fun calculateAverage(compatibility: HashMap<CompatibilityCategory, Int>): Int {
        var average = 0.0
        compatibility.forEach { average += it.value }
        average /= compatibility.size
        return roundValue(average)
    }

    fun roundValue(value: Double): Int {
        val diff = (value * 10 % 10) / 10.0
        val final = if (diff >= 0.5) value + (1.0 - diff) else value
        return final.toInt()
    }

    fun calculateCompatibility(
        myAccount: Account?, account: Account?,
        questions: MutableList<CompatibilityQuestion>,
        category: CompatibilityCategory
    ): Int {
        if (myAccount == null || account == null) return 0

        val categoryQuestions = questions.filter { it.group == category.group }.toMutableList()
        val compatibilityValue = calculateCompatibilityValue(myAccount, account, categoryQuestions)
        val percent =
            compatibilityValue.compatibilityValue * 100.0 / compatibilityValue.compatibilityMaxValue
        return roundValue(percent)
    }

    private fun calculateCompatibilityValue(
        myAccount: Account, account: Account, categoryQuestions: MutableList<CompatibilityQuestion>
    ): CompatibilityResult {
        val categoryQuestionIds = mutableListOf<String>()
        categoryQuestions.forEach { categoryQuestionIds.add("q${it.id}") }
        val myAnswersByCategory = getAnswersByCategory(myAccount, categoryQuestionIds)
        val answersByCategory = getAnswersByCategory(account, categoryQuestionIds)

        val completeQuestions = mutableListOf<CompatibilityQuestion>()

        var compatibilityValue = 0
        myAnswersByCategory.forEach { myAnswer ->
            val questionId = myAnswer.key
            val accountAnswer = answersByCategory[questionId] ?: CompatibilityAnswerStatus.NoSelect
            val question = categoryQuestions.first { "q${it.id}" == questionId }
            val valueByAnswer = getValueByAnswers(myAnswer.value, accountAnswer, question)
            if (valueByAnswer != -1) {
                completeQuestions.add(question)
                compatibilityValue += valueByAnswer
            }
        }

        var maxCompatibilityCategoryValue = 0
        completeQuestions.forEach {
            var maxValue = it.equallyScore ?: 0
            if ((it.oppositeScore ?: 0) > maxValue) maxValue = it.oppositeScore ?: 0
            if ((it.partlyScore ?: 0) > maxValue) maxValue = it.partlyScore ?: 0
            maxCompatibilityCategoryValue += maxValue
        }

        return CompatibilityResult(compatibilityValue, maxCompatibilityCategoryValue)
    }

    private fun getAnswersByCategory(
        account: Account,
        categoryQuestionIds: MutableList<String>
    ): HashMap<String, CompatibilityAnswerStatus> {
        val answers = account.info.compatibilityAnswers?.toString()
            ?.replace("{", "")
            ?.replace("}", "")
            ?.split(",")
            ?.sortedBy { it }

        val answersMap = hashMapOf<String, CompatibilityAnswerStatus>()
        answers?.forEach {
            val answer = it.split(":")
            val questionId = answer[0].replace("\"", "")
            if (categoryQuestionIds.contains(questionId))
                answersMap[questionId] = CompatibilityAnswerStatus.getStatus(answer[1].toInt())
        }
        return answersMap
    }

    private fun getValueByAnswers(
        myAnswer: CompatibilityAnswerStatus,
        accountAnswer: CompatibilityAnswerStatus,
        question: CompatibilityQuestion
    ): Int {
        val yes = CompatibilityAnswerStatus.Yes
        val no = CompatibilityAnswerStatus.No
        val maybe = CompatibilityAnswerStatus.Maybe
        val noSelect = CompatibilityAnswerStatus.NoSelect
        return when {
            myAnswer == accountAnswer -> question.equallyScore ?: 0
            (myAnswer == yes && accountAnswer == no) || (myAnswer == no && accountAnswer == yes) ->
                question.oppositeScore ?: 0
            myAnswer == noSelect || accountAnswer == noSelect -> -1
            else -> question.partlyScore ?: 0
        }
    }


    fun calculateSelfAnalysis(
        myAccount: Account?,
        questions: MutableList<CompatibilityQuestion>,
        category: CompatibilityCategory
    ): Int {
        if (myAccount == null) return 0

        val categoryQuestions = questions.filter {
            val categoryQuestionIds = if (AppVariant.isParadiz()) {
                when (category) {
                    CompatibilityCategory.Goals -> mutableListOf(1, 2, 3)
                    CompatibilityCategory.Libido, CompatibilityCategory.Lifestyle ->
                        mutableListOf(8, 9, 10)
                    CompatibilityCategory.Sexual -> mutableListOf(14, 15, 17)
                    CompatibilityCategory.Mindset -> mutableListOf(5, 6, 7)
                    CompatibilityCategory.Extreme, CompatibilityCategory.Habits ->
                        mutableListOf(16, 18, 19, 20)
                    else -> mutableListOf()
                }
            } else if (AppVariant.isElizium()) {
                when (category) {
                    CompatibilityCategory.Goals -> mutableListOf(1, 2, 3, 49)
                    CompatibilityCategory.Sexual -> mutableListOf(7, 8, 9, 13, 999)
                    CompatibilityCategory.Lifestyle -> mutableListOf(15, 16, 20, 24, 26)
                    CompatibilityCategory.Mindset -> mutableListOf(997, 28, 30, 32, 38)
                    CompatibilityCategory.Habits -> mutableListOf(998, 43, 44, 46, 47, 42)
                    else -> mutableListOf()
                }
            } else {
                when (category) {
                    CompatibilityCategory.Goals -> mutableListOf(1, 2, 3, 4)
                    CompatibilityCategory.Sexual -> mutableListOf(5, 7, 8)
                    CompatibilityCategory.Lifestyle -> mutableListOf(9, 10, 11, 12)
                    CompatibilityCategory.Mindset -> mutableListOf(13, 15, 18)
                    CompatibilityCategory.Habits -> mutableListOf(19, 20, 21)
                    else -> mutableListOf()
                }
            }
            categoryQuestionIds.contains(it.id)
        }.toMutableList()

        val categoryQuestionIds = mutableListOf<String>()
        categoryQuestions.forEach { categoryQuestionIds.add("q${it.id}") }
        val myAnswersByCategory = getAnswersByCategory(myAccount, categoryQuestionIds)

        val negativeQuestions =
            if (AppVariant.isFiorryOrHeaven()) mutableListOf(2, 12, 18, 19)
            else if (AppVariant.isParadiz()) mutableListOf(3, 9, 10)
            else mutableListOf(3, 28, 42, 43, 998)
        val positiveQuestions =
            if (AppVariant.isFiorryOrHeaven())
                mutableListOf(1, 3, 4, 5, 7, 8, 9, 10, 11, 13, 15, 20, 21)
            else if (AppVariant.isParadiz())
                mutableListOf(1, 2, 5, 6, 7, 8, 14, 15, 17, 16, 18, 19, 20)
            else mutableListOf(
                1, 2, 49, 7, 8, 9, 13, 999, 15, 16, 20, 24, 26, 997, 30, 32, 38, 44, 46, 47
            )

        var compatibilityValue = 0
        myAnswersByCategory.forEach { myAnswer ->
            val question = categoryQuestions.first { "q${it.id}" == myAnswer.key }
            val valueByAnswer = myAnswer.value.value
            when {
                negativeQuestions.contains(question.id) -> compatibilityValue -= valueByAnswer
                positiveQuestions.contains(question.id) -> compatibilityValue += valueByAnswer
            }
        }
        if (AppVariant.isFiorryOrHeaven()) {
            when (category) {
                CompatibilityCategory.Sexual -> compatibilityValue -= 3
                CompatibilityCategory.Mindset -> compatibilityValue += 1
                CompatibilityCategory.Habits -> compatibilityValue += 1
                else -> {}
            }
        } else if (AppVariant.isParadiz()) {
            when (category) {
                CompatibilityCategory.Goals -> compatibilityValue += 1
                CompatibilityCategory.Libido, CompatibilityCategory.Lifestyle -> compatibilityValue += 5
                CompatibilityCategory.Sexual -> compatibilityValue -= 3
                CompatibilityCategory.Mindset -> compatibilityValue -= 3
                CompatibilityCategory.Extreme, CompatibilityCategory.Habits -> compatibilityValue -= 4
                else -> {}
            }
        } else {
            when (category) {
                CompatibilityCategory.Sexual -> compatibilityValue -= 5
                CompatibilityCategory.Lifestyle -> compatibilityValue -= 5
                CompatibilityCategory.Mindset -> compatibilityValue -= 1
                CompatibilityCategory.Habits -> compatibilityValue += 6
                else -> {}
            }
        }

        val maxCompatibilityCategoryValue =
            if (AppVariant.isFiorryOrHeaven()) when (category) {
                CompatibilityCategory.Goals -> 8
                CompatibilityCategory.Lifestyle -> 8
                else -> 6
            } else if (AppVariant.isParadiz()) when (category) {
                CompatibilityCategory.Extreme, CompatibilityCategory.Habits -> 8
                else -> 6
            }
            else when (category) {
                CompatibilityCategory.Goals -> 8
                CompatibilityCategory.Habits -> 12
                else -> 10
            }

        val percent =
            compatibilityValue * 100.0 / maxCompatibilityCategoryValue
        val roundPercent = roundValue(percent)
        return if (roundPercent < 0) 0
        else if (roundPercent > 100) 100
        else roundPercent
    }

    private data class CompatibilityResult(
        val compatibilityValue: Int,
        val compatibilityMaxValue: Int
    )
}