    fun settingsSensitivePhotos(profileId: String?): Boolean {
        /*Параметр sensitive_photos:
         "full" - увiмкнено та прибирається для кожного користувача окремо
         "on" - увiмкнено
         "off" - вимкнено */

        var sensitivePhotos = if (AppVariant.isDebug()) "on" else "full"
        settings.forEach {
            if (it.key == "sensitive_photos") sensitivePhotos = it.value
        }
        val sensitiveType = when (sensitivePhotos) {
            "on" -> SensitiveType.ON
            "off" -> SensitiveType.OFF
            else -> SensitiveType.FULL
        }

        val showedSensitiveContentUserIds =
            JsonObjectConverter.stringToObject<List<String>>(getAppKeys().showedSensitiveContentUserIds)
                ?: listOf()

        return (!getAppKeys().showedSensitiveContentBox && sensitiveType == SensitiveType.ON)
                || (sensitiveType == SensitiveType.FULL
                && !showedSensitiveContentUserIds.contains(profileId))
    }

