    fun getPaywallSubscribeList(paywallType: Int, isTrialPage: Boolean = false): List<Billings> {
        if (isTrialPage) return mutableListOf(Billings.Unlim1Trial)

        val productIds = userAdaptyPaywalls.adaptyPaywallConfig?.getProductIdList()?.toMutableList()
        if (!productIds.isNullOrEmpty()) {
            val extraSubscribe = userAdaptyPaywalls.adaptyPaywallConfig?.getPaywallWithExtraAnnual()
            if (!extraSubscribe.isNullOrEmpty()) {
                if (productIds.contains(extraSubscribe)) productIds.remove(extraSubscribe)
            }
            val array = mutableListOf<Billings>()
            productIds.forEach { productId ->
                Billings.getBillingByProductId(productId)?.let { array.add(it) }
            }
            if (array.isNotEmpty()) return array
        }

        return when (paywallType) {
            3 -> mutableListOf(Billings.Unlim1Trial)
            6, 8 -> mutableListOf(Billings.Unlim0Trial7, Billings.Unlim1Trial)
            else -> mutableListOf(Billings.BetaUnlim12Discount, Billings.Unlim1, Billings.Unlim0_7)
        }
    }

