    fun getDefaultSubscribeList(subscribeType: SubscribeType): MutableList<Billings> {
        val productIds = userAdaptyPaywalls.adaptySubscriptionsConfig?.getProductIdList()
        if (!productIds.isNullOrEmpty()) {
            val array = mutableListOf<Billings>()
            productIds.forEach { productId ->
                if ((subscribeType == SubscribeType.UNLIMITED && Billings.isUnlimSubscribe(productId)) ||
                    (subscribeType == SubscribeType.PLUS && Billings.isPlusSubscribe(productId))
                ) {
                    Billings.getBillingByProductId(productId)?.let { array.add(it) }
                }
            }

            if (array.isNotEmpty()) return array
        }

        return if (subscribeType == SubscribeType.UNLIMITED) {
            arrayListOf(Billings.Unlim0_7, Billings.Unlim12, Billings.Unlim1)
        } else arrayListOf(Billings.BetaPlus0_7, Billings.Plus12, Billings.BetaPlus1)
    }

    fun getProposePageBillingType(
        paywallType: Int,
        subscribeType: SubscribeType,
        selectSecond: Boolean = false,
        showDiscount: Boolean = false
    ): Billings {

        val productIds = userAdaptyPaywalls.adaptyPaywallConfig?.getProductIdList()
        if (!productIds.isNullOrEmpty()) {
            val billing =
                getPaywallSubscribeList(paywallType).elementAtOrNull(if (selectSecond) 1 else 0)
            if (billing != null) return billing
        }

        fun weekSubscribe(): Billings {
            return if (subscribeType == SubscribeType.PLUS) {
                if (showDiscount) Billings.Plus0_7Promo else Billings.Plus0_7
            } else {
                if (showDiscount) Billings.Unlim0_7Promo else Billings.Unlim0_7
            }
        }

        fun monthSubscribe(): Billings {
            return if (subscribeType == SubscribeType.PLUS) {
                if (showDiscount) Billings.Plus1Promo else Billings.Plus1
            } else {
                if (showDiscount) Billings.Unlim1Promo else Billings.Unlim1
            }
        }

        return when (paywallType) {
            3 -> Billings.Unlim1Trial
            5, 12 -> {
                if (selectSecond) Billings.Unlim12Discount
                else monthSubscribe()
            }

            6 -> {
                if (selectSecond) Billings.Unlim1Trial
                else Billings.Unlim0Trial7
            }

            else -> {
                if (selectSecond) monthSubscribe()
                else weekSubscribe()
            }
        }
    }

