    init {
        userAdaptyPaywalls =
            JsonObjectConverter.stringToObject(getAppKeys().userAdaptyPaywalls)
                ?: UserAdaptyPaywalls()
        chatRequests.setAccountRepCallback(::chatRequest)
        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
            val account = getMyAccount()
            if (account?.isBlockForVerification() == true || (checkSettingsVerificationBlockDate(
                    account
                ) && getAppKeys().userRegistered)
            ) blockAccountForVerification()
        }

        val appVersion = AppVariant.appVersion
        adaptyManager.updateCustomParameter(AdaptyCustomParams.app_version, appVersion)
    }

    private fun chatRequest(result: Any) {
        when (result) {
            is UserChangeStatus -> {
                CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                    val userId = result.userId
                    val account = getAccountById(getId(userId))
                    account?.isOnline = result.isOnline
                    account?.lastActive = DateTimeConverterPlatform.getTimeZoneDateString()
                    saveAccount(account)
                    DelayedActionExecutor({
                        EventBusManager.post(UserConnected(userId, result.isOnline))
                    }, 1000)
                }
            }

            else -> {
            }
        }
    }

    fun subscribeByGoogle(
        productId: String,
        token: String,
        sameSubscribeType: Boolean,
        onSuccess: (AccountSubscriptionStatus?) -> Unit,
        onError: (String?) -> Unit = {}
    ) {
        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
            val myAccount = getMyAccount()
            val subscribeType = myAccount?.subscriptionStatus?.subscription?.type ?: 0
            accountRequests.subscribeByGoogle(
                productId,
                token,
                subscribeType != 0,
                onSuccess = { data ->
                    if (!sameSubscribeType) deleteChatAndWowLimits(onSuccess = {
                        activateChatAndWowLimits()
                    })
                    myAccount?.subscriptionStatus = data?.data
                    CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                        saveAccount(myAccount)
                        CoroutineScope(Dispatchers.Main).launch { onSuccess(data?.data) }
                    }
                },
                onError = { CoroutineScope(Dispatchers.Main).launch { onError(it) } })
        }
    }

    fun subscribeRecovery(
        productId: String, token: String, onSuccess: () -> Unit, onError: (String?) -> Unit = {}
    ) {
        accountRequests.subscribeRecovery(productId, token, onSuccess = { data ->
            CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                val account = getMyAccount()
                account?.subscriptionStatus = data?.data
                saveAccount(account)
                CoroutineScope(Dispatchers.Main).launch { onSuccess() }
            }
        }, onError = { CoroutineScope(Dispatchers.Main).launch { onError(it) } })
    }

    fun getLimitsByGenders(
        onSuccess: () -> Unit = {}, onError: () -> Unit = {}
    ) {
        accountRequests.getLimitsByGenders(onSuccess = {
            CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                val filter = getMyFilter() ?: AccountFilter()
                val myAccount = getMyAccount()
                val myGender = myAccount?.info?.iamList?.get(0)
                it?.data?.forEach {
                    if (it.gender == myGender) {
                        if (it.subsType == 0) {
                            filter.myGenderFreeChats = it.chats
                            filter.myGenderFreeWows = it.wows

                        } else if (it.subsType == 2) {
                            filter.myGenderUnlimChats = it.chats
                        } else {
                            filter.myGenderPlusChats = it.chats
                            filter.myGenderPlusWows = it.wows
                        }
                    }
                }
                saveAccountFilter(filter)
                CoroutineScope(Dispatchers.Main).launch { onSuccess() }
            }
        }, onError = { CoroutineScope(Dispatchers.Main).launch { onError() } })
    }

