    fun activateVoucher(
        voucher: String,
        onSuccess: (AccountSubscriptionStatus?) -> Unit = {},
        onError: (String?) -> Unit = {}
    ) {
        val currentTime = Date.currentTimeMillis()
        val oneDay = 24L * 60 * 60 * 1000
        val retryStartDatePromoCode = getAppKeys().retryStartDatePromoCode
        if (getAppKeys().countPromoCode >= 5 && currentTime - retryStartDatePromoCode < oneDay && AppVariant.isReleaseBuild()) {
            onError(null)
            return
        }
        if (currentTime - getAppKeys().retryStartDatePromoCode > oneDay) {
            getAppKeys().countPromoCode = 1
            getAppKeys().retryStartDatePromoCode = currentTime
        } else {
            getAppKeys().countPromoCode++
        }

        CoroutineScope(Dispatchers.Main).launch {
            val myAccount = getMyAccount()
            accountRequests.activateVoucher(
                voucher,
                onSuccess = { paymentResult ->
                    deleteChatAndWowLimits(onSuccess = { activateChatAndWowLimits() })
                    if (paymentResult?.data?.subscription == null) {
                        loadMyAccount(onSuccess = {
                            onSuccess(it?.subscriptionStatus)
                        }, onError = { onSuccess(null) })
                    } else {
                        myAccount?.subscriptionStatus = paymentResult.data
                        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                            saveAccount(myAccount)
                            onSuccess(paymentResult.data)
                        }
                    }
                },
                onError = {
                    CoroutineScope(Dispatchers.Main).launch { onError(it) }
                }
            )
        }
    }

