    private fun loadPaywallConfiguration(startPaywallType: PaywallType) {
        fun updateBetaParameterAndLoadNextConfig() {
            val hasBetaSubscribe = Billings.hasBetaSubscribe(
                userAdaptyPaywalls.adaptyPaywallConfig?.getProductIdList() ?: listOf()
            )
            adaptyManager.updateCustomParameter(
                AdaptyCustomParams.beta_subscriptions, hasBetaSubscribe.toString()
            ) { loadSettingsConfiguration(startPaywallType) }
        }

        adaptyManager.getPaywall(PaywallType.Paywall, onSuccess = {
            if (it is AdaptyPaywallConfig?) userAdaptyPaywalls.adaptyPaywallConfig = it
            if (startPaywallType != PaywallType.Paywall) loadDiscountConfiguration(startPaywallType)
            else updateBetaParameterAndLoadNextConfig()
        }, onError = {
            if (startPaywallType != PaywallType.Paywall) loadDiscountConfiguration(startPaywallType)
            else updateBetaParameterAndLoadNextConfig()
        })
    }

    private fun loadSubscriptionConfiguration(startPaywallType: PaywallType) {
        adaptyManager.getPaywall(PaywallType.Subscriptions, onSuccess = {
            if (it is AdaptySubscriptionsConfig?) userAdaptyPaywalls.adaptySubscriptionsConfig = it
            if (startPaywallType == PaywallType.Paywall) loadDiscountConfiguration(startPaywallType)
            else loadPaywallConfiguration(startPaywallType)
        }, onError = {
            if (startPaywallType == PaywallType.Paywall) loadDiscountConfiguration(startPaywallType)
            else loadPaywallConfiguration(startPaywallType)
        })
    }

    private fun loadDiscountConfiguration(startPaywallType: PaywallType) {
        adaptyManager.getPaywall(
            PaywallType.Discount,
            onSuccess = {
                if (it is AdaptyDiscountConfig?) userAdaptyPaywalls.adaptyDiscountConfig = it
                if (startPaywallType == PaywallType.Subscriptions)
                    loadSettingsConfiguration(startPaywallType)
            },
            onError = {
                if (startPaywallType == PaywallType.Subscriptions)
                    loadSettingsConfiguration(startPaywallType)
            })
    }

    private fun loadSettingsConfiguration(startPaywallType: PaywallType) {
        fun loadNextPaywall() {
            val parameters = listOf(
                AdaptyCustomParameter(
                    AdaptyCustomParams.people_screen_swipes_priority,
                    stringValue = (userAdaptyPaywalls.adaptySettingsConfig?.peopleScreenSwipesPriority
                        ?: true).toString()
                ),
                AdaptyCustomParameter(
                    AdaptyCustomParams.people_screen_block_default,
                    stringValue = (userAdaptyPaywalls.adaptySettingsConfig?.peopleScreenBlockDefault
                        ?: true).toString()
                ),
                AdaptyCustomParameter(
                    AdaptyCustomParams.people_screen_type,
                    intValue = userAdaptyPaywalls.adaptySettingsConfig?.getPeopleScreenType() ?: 2
                )
            )

            adaptyManager.updateCustomParameters(parameters) {
                loadSubscriptionConfiguration(startPaywallType)
            }
        }

        adaptyManager.getPaywall(
            PaywallType.Settings,
            onSuccess = {
                if (it is AdaptySettingsConfig?) userAdaptyPaywalls.adaptySettingsConfig = it
                if (startPaywallType != PaywallType.Subscriptions) loadNextPaywall()
            },
            onError = {
                if (startPaywallType != PaywallType.Subscriptions)
                    loadSubscriptionConfiguration(startPaywallType)
            })
    }

