    ///region Server
    private var lastLoadMyAccount = 0L
    var lastUserVerificationStatus: String? = null

    fun loadMe(
        onSuccess: (Account?) -> Unit = {},
        onError: () -> Unit = {},
        showErrorMessage: Boolean = true,
        ignoreTime: Boolean = false,
        saveWithoutMerge: Boolean = true
    ) {
        val time = Date.currentTimeMillis()
        if (time - lastLoadMyAccount > 3000 || ignoreTime) {
            lastLoadMyAccount = time
            loadMyAccount(
                onSuccess = { account ->
                    if (account?.emailVerified != true) {
                        EventBusManager.post(EmailNotVerified())
                    }
                    account?.id?.let { id -> getAppKeys().userId = id }
                    getAppKeys().userLogin = account?.login ?: ""
                    CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                        val lastMyAccountData = getMyAccount()
                        if (saveWithoutMerge) saveMyAccountWithoutMerge(account)
                        else saveAccount(account)
                        if (account?.isBlockForVerification() != true &&
                            !checkSettingsVerificationBlockDate(account)
                        ) {
                            if (account?.photoVerificationStatus != lastUserVerificationStatus) {
                                if (account?.getVerificationStatus() == AccountVerificationStatus.VERIFIED) {
                                    isBlockAccountForVerification = false
                                }

                                ChatRequests.userBlockByVerification = false
                                if (getAppKeys().userRegistered) chatRequests.connectWebSocket()
                                lastUserVerificationStatus = account?.photoVerificationStatus
                                delay(500L)
                                EventBusManager.post(UpdateVerificationProfile(account))
                            }
                        } else blockAccountForVerification()
                        resetSubscriptionAccount(account, lastMyAccountData, onSuccess, onError)
                    }
                },
                onError = { CoroutineScope(Dispatchers.Main).launch { onError() } },
                showErrorMessage = showErrorMessage
            )
        } else {
            if (myAccount != null) onSuccess(myAccount)
            else {
                CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                    val account = getMyAccount()
                    CoroutineScope(Dispatchers.Main).launch { onSuccess(account) }
                }
            }
        }
    }

    var lastSubscribeType: Int = -1

    private fun resetSubscriptionAccount(
        myAccount: Account?,
        lastMyAccountData: Account?,
        onSuccess: (Account?) -> Unit,
        onError: () -> Unit
    ) {
        if (myAccount == null) {
            CoroutineScope(Dispatchers.Main).launch { onSuccess(myAccount) }
            return
        }
        val subscribeType = myAccount.subscriptionStatus?.subscription?.type ?: 0
        val currentSubscribeType = when (subscribeType) {
            1 -> SubscribeType.PLUS
            2 -> SubscribeType.UNLIMITED
            else -> SubscribeType.FREE
        }

        if (lastSubscribeType == subscribeType) {
            EventBusManager.post(SubscribeSettingsUpdate(currentSubscribeType))
            CoroutineScope(Dispatchers.Main).launch { onSuccess(myAccount) }
            return
        }

        fun updateCurrentSubscribe() {
            val lastAccountSubscribeType =
                lastMyAccountData?.subscriptionStatus?.subscription?.type ?: 0
            if (lastAccountSubscribeType > 0 && subscribeType == 0) {
                getAppKeys().userSubscribeOtherAccount = false
                deleteChatAndWowLimits()
            }

            val subscribeExpiredMinutes =
                DateTimeConverterPlatform.getDiffTimeInMinutes(myAccount.subscriptionStatus?.expiredAt)
            if (subscribeType == 0 && subscribeExpiredMinutes > 2 &&
                (!myAccount.notVisibleForGenders.isNullOrEmpty() || myAccount.isInvisible == true ||
                        (myAccount.showMinAge ?: 18) > 18 || (myAccount.showMaxAge ?: 100) < 100)
            ) {
                myAccount.notVisibleForGenders = mutableListOf()
                myAccount.isInvisible = false
                myAccount.showMinAge = 18
                myAccount.showMaxAge = 100
                val updateAccount = Account()
                updateAccount.notVisibleForGenders = mutableListOf()
                updateAccount.isInvisible = false
                updateAccount.showMinAge = 18
                updateAccount.showMaxAge = 100
                updateAccount(updateAccount)
            }

            if (lastSubscribeType != -1) EventBusManager.post(SubscribeSuccess(currentSubscribeType))
            lastSubscribeType = subscribeType

            CoroutineScope(Dispatchers.Main).launch { onSuccess(myAccount) }
        }

        val haveSubscribe = subscribeType == 1 || subscribeType == 2

        if (haveSubscribe) {
            updateCurrentSubscribe()
            return
        } else {
            CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                val filter = getMyFilter()
                filter?.selectLat = 0.0
                filter?.selectLon = 0.0
                filter?.selectCity = ""
                //filter?.filters?.avatar = false
                filter?.filters?.online = false
                filter?.filters?.onlyVerified = false
                filter?.filters?.looking = true
                filter?.filters?.newUsers = false
                filter?.filters?.searchByCompatibility = false
                filter?.filters?.compatibility = AccountFilterCompatibilities()
                saveAccountFilter(filter)
                updateCurrentSubscribe()
            }
        }
    }

