    fun loadAccountsByFilter(
        accountFilter: AccountFilter?,
        from: Int = 0,
        to: Int = 27,
        type: Int = 0,
        onSuccess: (MutableList<Account>?) -> Unit = {},
        onError: () -> Unit = {}
    ) {
        if (isBlockAccountForVerification) return
        try {
            CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                val filter = accountFilter ?: AccountFilter()

                if (!filter.selectCity.isNullOrEmpty()) {
                    val city =
                        filter.cities.firstOrNull { it.lat == filter.selectLat && it.lon == filter.selectLon }
                    if (city != null) filter.filters.coordinates =
                        AccountCoordinates(city.lat, city.lon)
                    else filter.filters.coordinates =
                        AccountCoordinates(filter.localLat, filter.localLon)
                } else filter.filters.coordinates =
                    AccountCoordinates(filter.localLat, filter.localLon)
                filter.offset = from
                filter.limit = to
                filter.filters.sex = getMyAccount()?.info?.interestedIn
                filter.type = type

                accountRequests.loadAccountsByFilter(filter, onSuccess = { result ->
                    val accounts = result?.data
                    CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                        saveAccounts(accounts)
                        CoroutineScope(Dispatchers.Main).launch { onSuccess(accounts) }
                    }
                }, onError = { CoroutineScope(Dispatchers.Main).launch { onError() } })
            }
        } catch (e: Throwable) {
            CoroutineScope(Dispatchers.Main).launch { onError() }
        }
    }

