                    filter.cities.firstOrNull { it.lat == filter.selectLat && it.lon == filter.selectLon }
                if (city != null) filter.filters.coordinates =
                    AccountCoordinates(city.lat, city.lon)
                else filter.filters.coordinates =
                    AccountCoordinates(filter.localLat, filter.localLon)
            } else filter.filters.coordinates =
                AccountCoordinates(filter.localLat, filter.localLon)
            filter.offset = from
            filter.limit = to
            filter.filters.sex = getMyAccount()?.info?.interestedIn

            val result = accountRequests.loadAccountsByFilterWithResult(filter)
            val accounts = result?.data
            CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                saveAccounts(accounts)
            }
            return accounts
        } catch (e: Throwable) {
            null
        }
    }

