    fun checkBanDevice(login: () -> Unit) {
        val isEmulator = platformInfoManager.isEmulator(settingsBlockByEmulatorValues())
        if (AppVariant.isPlayMarketBuild() && isEmulator) {
            banError()
            return
        }
        platformInfoManager.getDeviceId { deviceId ->
            checkBanDevice(deviceId, onSuccess = { if (it == false) login() else banError() })
        }
    }

    private var lastBanStatus = 0

    private fun checkBanAccount(
        account: Account?,
        callback: () -> Unit,
        logout: (String) -> Unit = {}
    ) {
        val isEmulator = platformInfoManager.isEmulator(settingsBlockByEmulatorValues())
        if (AppVariant.isPlayMarketBuild() && isEmulator) {
            banError()
            return
        }
        if (account?.banStatus == 3 && lastBanStatus == 3) {
            callback()
            return
        }
        lastBanStatus = 0
        when (account?.banStatus) {
            3 -> platformInfoManager.getDeviceId { deviceId ->
                val changeBanStatus =
                    DateTimeConverterPlatform.stringToDate(account.banStatusChangedAt)
                val banStatusSevenDays = (changeBanStatus ?: 0) + (7L * 24 * 60 * 60 * 1000)
                if (changeBanStatus == null || Date.currentTimeMillis() > banStatusSevenDays) callback()
                else unBanDevice(deviceId, onSuccess = {
                    lastBanStatus = 3
                    callback()
                })
            }

            2 -> banDevice({ logout.invoke("acc_permanent_banned") })
            else -> checkBanDevice { callback() }
        }
    }

    fun banDevice(
        logout: () -> Unit = { clearData("acc_device_banned") }, accountId: Int? = null
    ) {
        fun ban() {
            platformInfoManager.getDeviceId { deviceId ->
                banDevice(deviceId, onSuccess = {
                    if (getAppKeys().userToken.isNotEmpty()) logout()
                    banError()
                })
            }
        }
        if (accountId == null) ban() else {
            CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                val myAccount = getMyAccount()
                if (myAccount?.id == accountId.toString()) ban()
            }
        }
    }

    fun banAccount(accountId: Int?) {
        if (accountId == null) banError() else {
            CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                val myAccount = getMyAccount()
                if (myAccount?.id == accountId.toString()) banError()
            }
        }
    }

    fun banError() {
        if (getAppKeys().userToken.isNotEmpty()) clearData("acc_banned")
        CoroutineScope(Dispatchers.Main).launch {
            delay(1000)
            val isEmulator = platformInfoManager.isEmulator(settingsBlockByEmulatorValues())
            val text = ResManager.getString(Res.string.error_message_account_block_text)
            val btnText = ResManager.getString(Res.string.error_message_account_block_btn)
            if (isEmulator) accountRequests.networkSession.showMessage(message = text)
            else accountRequests.networkSession.showMessage(
                EDialogType.DIALOG_BAN_USER,
                dialogText = text,
                hint = btnText,
                callback = {
                    accountRequests.networkSession.dismissMessage()
                    platformInfoManager.getDeviceId { deviceId ->
                        var accountId = getAppKeys().userId
                        val title =
                            if (accountId.isNotEmpty()) ResourceManager.getStringByIdWithParams(
                                "error_message_account_block_email_title", accountId, ""
                            ) else ResourceManager.getStringByIdWithParams(
                                "error_message_device_block_email_title", deviceId, ""
                            )
                        val message =
                            if (accountId.isNotEmpty()) ResourceManager.getStringByIdWithParams(
                                "error_message_account_block_email_message", accountId, ""
                            ) else ResourceManager.getStringByIdWithParams(
                                "error_message_device_block_email_message", deviceId, ""
                            )
                        platformInfoManager.sendEmail(title, message)
                        EventBusManager.post(OnCloseBanDialog())
                    }
                },
                onCancel = {
                    accountRequests.networkSession.dismissMessage()
                    EventBusManager.post(OnCloseBanDialog())
                })
        }
    }

