    private var returnLocationResult = false
    private var waitLocationResult = false

    fun updateUserLocation(
        onSuccess: (AccountFilter, Boolean) -> Unit = { _, _ -> },
        onError: () -> Unit = {},
        blockByLocation: () -> Unit = {}
    ) {

        fun updateCustomLocation(lat: Double, lon: Double) {
            if (lat != 0.0 && lon != 0.0) {
                waitLocationResult = true

                updateMyDeviceInfo(lat, lon)

                updateUserCity(lat, lon, onSuccess = {
                    waitLocationResult = false
                    locationUtils.updateLocationSuccessfully()
                    if (it.localLat != 0.0 && it.localLon != 0.0) {
                        returnLocationResult = true
                        onSuccess(it, true)
                    }
                }, onError = {
                    waitLocationResult = false
                    returnLocationResult = false
                    onError()
                }, blockByLocation)
            }
        }

        fun setDefaultLocation() {
            CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                val myAccount = getMyAccount()
                val lat = myAccount?.location?.lat ?: 0.0
                val lon = myAccount?.location?.lon ?: 0.0
                updateCustomLocation(lat, lon)
            }
            DelayedActionExecutor({
                if (returnLocationResult) return@DelayedActionExecutor
                if (waitLocationResult) {
                    setDefaultLocation()
                    return@DelayedActionExecutor
                }
                val defaultLat = if (AppVariant.isEliziumOrParadiz()) 50.4423864 else 34.0207305
                val defaultLon = if (AppVariant.isEliziumOrParadiz()) 30.4653865 else -118.6919213
                updateUserCity(
                    defaultLat, defaultLon, onSuccess = {
                        onSuccess(it, false)
                    }, onError, blockByLocation
                )
            }, 1000L * 45)
        }

        returnLocationResult = false
        locationUtils.callback = { lat, lon ->
            if (lat != 0.0 && lon != 0.0) {
                updateCustomLocation(lat, lon)
            }
        }

        locationUtils.errorCallback = {
            loggedError(ScreenEnum.LocationGetCoordinates, error = "Init location manager: $it")
        }

        var counter = 0
        fun getLocation() {
            counter++
            locationUtils.getLocation()
            DelayedActionExecutor({
                if (!returnLocationResult) {
                    if (counter <= 15) getLocation()
                    else loggedError(
                        ScreenEnum.LocationGetCoordinates, error = "Can not get coordinates"
                    )
                }
            }, 3000)
        }
        getLocation()


        val delayedActionExecutor = DelayedActionExecutor(1000L * 15) {
            if (returnLocationResult) return@DelayedActionExecutor
            locationUtils.getLocation(true)
            setDefaultLocation()
        }
        delayedActionExecutor.start()
    }

    fun updateUserCity(
        lat: Double,
        lon: Double,
        onSuccess: (AccountFilter) -> Unit = {},
        onError: () -> Unit = {},
        blockByLocation: () -> Unit = {}
    ) {
        var updateAddressRetries = 0
        val deviceId = getAppKeys().appDeviceId
        fun saveFilter() {
            CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                val filter = getMyFilter() ?: AccountFilter(deviceId)
                filter.localLat = lat
                filter.localLon = lon
                saveAccountFilter(filter)
                onSuccess(filter)
            }
        }

        fun getLocation() {
            try {
                fun updateAddress(userLocationParams: UserLocationParams) {

                    if (Constants.blockCountryCodes.contains(userLocationParams.countryCode)) {
                        blockByLocation()
                        returnLocationResult = true
                        return
                    }
                    returnLocationResult = false
                    saveFilter()

                    val adminArea = userLocationParams.adminArea
                    val location = AccountLocation(
                        userLocationParams.city, lat, lon, userLocationParams.countryName, adminArea
                    )

                    accountRequests.updateLocationAccount(location, onSuccess = {
                        if (getAppKeys().userRefreshToken.isEmpty()) initRefreshToken()
                        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                            val myAccount = getMyAccount()
                            myAccount?.location = location
                            saveAccount(myAccount)
                        }
                    }, onError = {
                        loggedError(ScreenEnum.LocationUpdate, error = it ?: "")
                        if (updateAddressRetries < 3) {
                            updateAddressRetries++
                            updateAddress(userLocationParams)
                        }
                        CoroutineScope(Dispatchers.Main).launch { onError() }
                    })
                }

                locationUtils.getCityAddress(lat, lon) { userLocation ->
                    if (userLocation.city.isNotEmpty()) {
                        updateAddress(userLocation)
                        return@getCityAddress
                    }
                    /*val addresses = geocoder.getFromLocation(lat, lon, 5) ?: mutableListOf()
                    for (address in addresses) {
                        val city = LocationUtils.getCity(address)
                        if (city.isNotEmpty()) {
                            updateAddress(address, city)
                            return
                        }
                    }*/
                    loggedError(
                        ScreenEnum.LocationGetPlace,
                        error = "Not found place by coordinates: lat=$lat; lon=$lon"
                    )
                }
            } catch (e: Throwable) {
                e.message
