    private var updateMyDeviceInfoFirstTime = true
    private var updateMyDeviceInfoRepeater: DelayedActionExecutor? = null

    fun updateMyDeviceInfo(lat: Double, lon: Double) {
        updateMyDeviceInfoRepeater?.pause()
        updateMyDeviceInfoRepeater = null
        val oneHour = if (AppVariant.isTestBuild()) 1000L * 60 else 1000L * 60 * 60

        fun sendDeviceInfoData(lat: Double, lon: Double) {
            if (!AppVariant.appActive || !getAppKeys().userRegistered) return
            if (lat == 0.0 && lon == 0.0) {
                updateMyDeviceInfoRepeater?.start(1000L * 10)
                return
            }

            val data = getUserAgentString()
            getAppKeys().lastSendDeviceInfoTime = Date.currentTimeMillis()

            val jsonObject = hashMapOf<String, JsonPrimitive>()
            var batteryLevel = -100
            data.forEach {
                if (it.key == "batteryLevel") batteryLevel = it.value.toInt()
                jsonObject[it.key] = JsonPrimitive(it.value)
            }

            val deviceId = platformInfoManager.getDeviceId()
            jsonObject["deviceId"] = JsonPrimitive(deviceId)
            val dataJson = kotlinx.serialization.json.JsonObject(jsonObject)

            accountRequests.updateMyDeviceInfo(dataJson, batteryLevel, deviceId, lon, lat)
            updateMyDeviceInfoRepeater?.start(oneHour)
        }

        val currentTime = Date.currentTimeMillis()
        val lastUpdateTime = currentTime - getAppKeys().lastSendDeviceInfoTime
        val delayTime = if (lastUpdateTime < oneHour) oneHour - lastUpdateTime else oneHour

        updateMyDeviceInfoRepeater = DelayedActionExecutor(delayTime) {
            CoroutineScope(Dispatchers.Main).launch {
                val newLat = getMyAccount()?.location?.lat ?: lat
                val newLon = getMyAccount()?.location?.lon ?: lon
                sendDeviceInfoData(newLat, newLon)
            }
        }
        if (lastUpdateTime >= oneHour) sendDeviceInfoData(lat, lon)
        else updateMyDeviceInfoRepeater?.start()
    }

