    var lastRefreshToken = 0L

    fun refreshToken(onSuccess: () -> Unit = {}) {
        val time = Date.currentTimeMillis()
        if (time - lastRefreshToken > 1000) {
            lastRefreshToken = time

            accountRequests.refreshToken(onSuccess = {
                startRefreshToken = false
                val token = it?.data?.token
                if (!token.isNullOrEmpty()) {
                    getAppKeys().userToken = token
                    KtorClient.refreshedToken = token
                }
                val refreshToken = it?.data?.refreshToken
                if (!refreshToken.isNullOrEmpty()) getAppKeys().userRefreshToken = refreshToken
                chatRequests.reconnectWebSocket()
                DelayedActionExecutor(
                    { KtorClient.resumeQueue() }, 1000
                )
                onSuccess()
            }, onError = {
                startRefreshToken = false
                clearData("refresh_token_expired")
                CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
                    delay(500)
                    val text = ResManager.getString(Res.string.error_message_token_refresh_text)
                    accountRequests.networkSession.showMessage(message = text)
                }
            })
        } else {
            startRefreshToken = false
        }
    }

    private fun initRefreshToken(onSuccess: () -> Unit = {}) {
        accountRequests.initRefreshToken(onSuccess = {
            val token = it?.data?.token
            if (!token.isNullOrEmpty()) getAppKeys().userToken = token
            val refreshToken = it?.data?.refreshToken
            if (!refreshToken.isNullOrEmpty()) getAppKeys().userRefreshToken = refreshToken
            chatRequests.reconnectWebSocket()
            onSuccess()
        })
    }

