    fun updateFilter(filters: AccountFilters, subsType: Int) {
        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
            val myFilter = getMyFilter() ?: AccountFilter()
            filters.withCompatibility?.let { myFilter.filters.withQuestionnaire = it }
            filters.ageFrom?.let { myFilter.filters.age.from = it }
            filters.ageTo?.let { myFilter.filters.age.to = it }
            filters.withPhoto?.let { myFilter.filters.avatar = it }
            if (subsType >= 1) {
                //filters.withPhoto?.let { myFilter.filters.avatar = it }
                filters.interestedMyGender?.let { myFilter.filters.looking = it }
            }
            filters.compatibilities?.let {
                myFilter.filters.compatibility = it
                myFilter.filters.compatibility.useDefaultValues = false
                //myFilter.filters.searchByCompatibility = subsType == 2 && filters.withCompatibility == true
            }
            saveAccountFilter(myFilter)
        }
    }

