    fun uploadFilter(filter: AccountFilter? = null) {
        if (!getAppKeys().userRegistered) return
        CoroutineScope(Dispatchers.Main).launch { /* runBlocking */
            val myFilter = filter ?: getMyFilter() ?: AccountFilter()
            val filters = AccountFilters()
            filters.withCompatibility = myFilter.filters.withQuestionnaire
            filters.withPhoto = myFilter.filters.avatar
            filters.interestedMyGender = myFilter.filters.looking
            filters.ageFrom = myFilter.filters.age.from
            filters.ageTo = myFilter.filters.age.to ?: 100
            filters.compatibilities = myFilter.filters.compatibility
            accountRequests.updateAccountFilter(filters)
        }
    }

