    suspend fun getAccountById(userId: Id): Account? = withContext(Dispatchers.Default) {
        database.getAccountById(userId)
    }

    suspend fun getMyAccount(): Account? = withContext(Dispatchers.Default) {
        database.getAccountByLogin(getAppKeys().userLogin)
    }

    suspend fun saveAccount(account: Account?) = withContext(Dispatchers.Default) {
        if (account?.login == getAppKeys().userLogin) {
            val lastAccountData = myAccount ?: getMyAccount()
            if (account.info.iamList.isNullOrEmpty()) {
                account.info.iamList = lastAccountData?.info?.iamList
            }
            if (account.info.interestedIn.isNullOrEmpty()) {
                account.info.interestedIn = lastAccountData?.info?.interestedIn
            }
            myAccount = account
            database.saveMyAccount(account, getAppKeys().userLogin)
        } else {
            database.saveAccount(account)
        }
    }

    private suspend fun saveMyAccountWithoutMerge(account: Account?) =
        withContext(Dispatchers.Default) {
            val lastAccountData = myAccount ?: getMyAccount()
            if (account?.info?.iamList.isNullOrEmpty()) {
                account?.info?.iamList = lastAccountData?.info?.iamList
            }
            if (account?.info?.interestedIn.isNullOrEmpty()) {
                account?.info?.interestedIn = lastAccountData?.info?.interestedIn
            }
            myAccount = account
            database.saveAccountWithoutMerge(account)
        }

