@Composable
fun JsSubscriptionButtonContent(
    periodTitle: String,
    textPrices: TextPrices,
    isPopular: Boolean,
    isUnlim: Boolean,
    colorList: List<Color>,
    onSelected: Boolean,
    isNewDesign: Boolean
) {
    Row(
        modifier = Modifier
            .fillMaxSize()
            .padding(start = 24.dp, end = 12.dp, top = 8.dp, bottom = 8.dp),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Column(
            modifier = Modifier
                .fillMaxHeight()
                .width(0.6f.toPercent()),
            verticalArrangement = Arrangement.Center
        ) {
            Row {
                JsAutoResizeText(
                    text = periodTitle.uppercase(),
                    maxTextSize = 14,
                    fontWeight = FontWeight.Medium
                )

                if (isPopular) {
                    if (onSelected && !isNewDesign) {
                        val boxBackgroundColor =
                            if (isUnlim) JsMainTheme.colors.subscribe_unlim_popular_color
                            else JsMainTheme.colors.subscribe_plus_popular_color
                        Box(
                            modifier = Modifier
                                .padding(start = 8.dp)
                                .clipByCorner(15)
                                .background(boxBackgroundColor),
                            contentAlignment = Alignment.Center
                        ) {
                            JsTextView(
                                text = stringResource(Res.string.onboarding_propose_subscription_popular),
                                textSize = 10,
                                modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp),
                                textColor = JsMainTheme.colors.text_color_default,
                                fontWeight = FontWeight.Medium,
                            )
                        }
                    } else {
                        Box(
                            modifier = Modifier
                                .padding(start = 8.dp)
                                .clipByCorner(15)
                                .gradientBackground(colorList, 90),
                            contentAlignment = Alignment.Center
                        ) {
                            JsTextView(
                                text = stringResource(Res.string.onboarding_propose_subscription_popular),
                                textSize = 10,
                                modifier = Modifier.padding(horizontal = 8.dp, vertical = 2.dp),
                                textColor = JsMainTheme.colors.text_color_default,
                                fontWeight = FontWeight.Medium,
                            )
                        }
                    }
                }
            }

            Row {
                val textPrice =
                    textPrices.textPriceDiscountPeriod.ifEmpty { textPrices.textPricePeriod }
                if (textPrices.textPriceDiscountPeriod.isNotEmpty()) {
                    JsAutoResizeText(
                        modifier = Modifier
                            .padding(end = 8.dp)
                            .align(Alignment.Bottom),
                        text = textPrices.textPricePeriod,
                        maxTextSize = 16,
                        minTextSize = 6,
                        fontWeight = FontWeight.Medium,
                        textDecoration = TextDecorationLine.LineThrough,
                    )
                }

                JsAutoResizeText(
                    text = textPrice,
                    maxTextSize = 20,
                    minTextSize = 6,
                    fontWeight = FontWeight.Medium
                )


            }
        }

        Box(
            modifier = Modifier
                .fillMaxHeight()
                .padding(start = 8.dp, top = 2.dp, bottom = 2.dp)
                .width(0.4f.toPercent())
                .clipByCorner(25)
                .background(JsMainTheme.colors.main_color_white_transparent_70),
            contentAlignment = Alignment.Center
        ) {
            JsAutoResizeText(
                modifier = Modifier.padding(horizontal = 6.dp),
                text = textPrices.textDefaultPricePeriod,
                maxTextSize = 16,
                minTextSize = 6,
                color = JsMainTheme.colors.main_color_black,
                fontWeight = FontWeight.Medium,
                textAlign = TextAlign.Center,
                maxLines = 1,
            )
        }
    }
}

@Composable
fun getTextPriceCompose(
    productDetails: PurchaseInfo,
    discountDetails: PurchaseInfo?,
    period: SubscriptionPeriod,
    weekPrice: Double,
    isWeekFormat: Boolean = true
): TextPrices {
    var currentPrice = ""
    var currentPriceForWeek = ""
    var currentPriceDiscount = ""
    var currencyPercentDiscountFormat = ""
    val billingManager by di.instance<IBillingManager>()
    val skuDetails =
        billingManager.getSubscribePrice(productDetails.productId) ?: return TextPrices()
    val priceCurrentCode = skuDetails.priceCurrencyCode
    var discountPriceCurrentCode = priceCurrentCode
    val price = skuDetails.priceAmountMicros / 1000000.0
    var discountPrice = price
    val discountSkuDetails = billingManager.getSubscribePrice(discountDetails?.productId)
    val introductoryPrice = discountSkuDetails?.let { it.priceAmountMicros / 1000000.0 } ?: 0.0

    if (introductoryPrice == 0.0) {
        val priceFormat = getPriceFormat(price)
        val priceString = "$priceCurrentCode $priceFormat"
        currentPrice = priceString
    } else {
        discountPriceCurrentCode = discountSkuDetails?.priceCurrencyCode ?: priceCurrentCode
        val priceFormatForWeek = getProductWeekPrice(productDetails, price, isWeekFormat)
        val priceFormatForWeekText =
            getPriceFormat(priceFormatForWeek, changeFormat = introductoryPrice != 0.0)
        currentPriceForWeek = "$priceCurrentCode $priceFormatForWeekText"

        discountPrice = introductoryPrice

        val priceFormat = getPriceFormat(price, true)
        val introductoryFormat = getPriceFormat(introductoryPrice, true)

        var currencyPercentDiscount = (price - introductoryPrice) * 100 / price
        if (currencyPercentDiscount % 5 > 0) {
            currencyPercentDiscount += (5 - currencyPercentDiscount % 5)
        }
        currencyPercentDiscountFormat = getPriceFormat(
            currencyPercentDiscount,
            percentFormat = true
        )

        currentPriceDiscount = "$discountPriceCurrentCode $introductoryFormat"
        currentPrice = "$priceCurrentCode $priceFormat"
    }

    val monthFormat = stringResource(
        if (isWeekFormat) Res.string.subscribe_settings_weekly_text
        else Res.string.subscribe_settings_month_text
    ).lowercase()


    val discountText: String
    if (period == SubscriptionPeriod.WEEK) {
        val discountValue = discountPrice
        discountText = getPriceFormat(discountValue)
    } else {
        val discountValue = getProductWeekPrice(productDetails, discountPrice, isWeekFormat)
        discountText =
            getPriceFormat(discountValue, changeFormat = introductoryPrice != 0.0)
        var discountPercent = (weekPrice - discountValue) * 100 / weekPrice
        if (discountPercent % 1 >= 0.5) discountPercent += 1
    }
    return TextPrices(
        currentPrice,
        currentPriceForWeek,
        "$discountPriceCurrentCode $discountText $monthFormat",
        currentPriceDiscount,
        currencyPercentDiscountFormat
    )

}