package kotpref.models.typeConverter

import kotlinx.datetime.Clock
import kotlinx.datetime.DatePeriod
import kotlinx.datetime.DateTimeUnit
import kotlinx.datetime.Instant
import kotlinx.datetime.LocalDateTime
import kotlinx.datetime.LocalTime
import kotlinx.datetime.TimeZone
import kotlinx.datetime.minus
import kotlinx.datetime.number
import kotlinx.datetime.periodUntil
import kotlinx.datetime.toInstant
import kotlinx.datetime.toLocalDateTime


object DateTimeConverter {

    var dateFormat = "yyyy-mm-dd'T'HH:mm:ss'Z'"
    var dateFormatSecond = "yyyy-MM-dd'T'HH:mm:ss"

    var fullFormat = "dd.MM.yyyy HH:mm:ss"
    var shortDate = "dd.MM.yyyy"
    var shortDateFormat = "yyyy-MM-dd"

    var dateWithTimeFormat = "HH:mm dd.MM.yyyy"
    var dateWithTimeAndMonthName = "HH:mm dd MMM yyyy"
    var dateWithMonthNameFormat = "dd MMM yyyy"

    var timeFormat = "HH:mm"
    var timeFormatWithMonthName = "HH:mm dd MMM"

    fun dateToString(data: LocalDateTime? = null, format: String = dateFormat): String {
        val currentMoment: Instant = Clock.System.now()
        val localTime = data ?: currentMoment.toLocalDateTime(TimeZone.currentSystemDefault())
        val year = localTime.year
        val month = localTime.month.number
        val day = localTime.dayOfMonth

        val hours = localTime.hour
        val minutes = localTime.minute
        val seconds = localTime.second

        val monthString = if (month < 10) "0$month" else "$month"
        val daysString = if (day < 10) "0$day" else "$day"
        val hoursString = if (hours < 10) "0$hours" else "$hours"
        val minutesString = if (minutes < 10) "0$minutes" else "$minutes"
        val secondsString = if (seconds < 10) "0$seconds" else "$seconds"

        val monthName = getMonthName(month)

        return when (format) {
            dateFormat -> "${year}-${monthString}-${daysString}T${hoursString}:${minutesString}:${secondsString}Z" //"yyyy-mm-dd'T'HH:mm:ss'Z'"
            dateFormatSecond -> "${year}-${monthString}-${daysString}T${hoursString}:${minutesString}:${secondsString}" //"yyyy-mm-dd'T'HH:mm:ss"

            fullFormat -> "${day}.${month}.${year}" //dd.MM.yyyy HH:mm:ss
            shortDate -> "${day}.${month}.${year}" //"dd.MM.yyyy"
            shortDateFormat -> "${year}-${monthString}-${daysString}" //"yyyy-MM-dd"

            dateWithTimeFormat -> "${hoursString}:${minutesString}, ${day}.${month}.${year}" //"HH:mm dd.MM.yyyy"
            dateWithTimeAndMonthName -> "${hoursString}:${minutesString}, $day $monthName $year" //"HH:mm dd MMM yyyy"
            dateWithMonthNameFormat -> "$day $monthName $year" //"dd MMM yyyy"

            timeFormat -> "${hoursString}:${minutesString}" //"HH:mm"
            timeFormatWithMonthName -> "${hoursString}:${minutesString} $day $monthName" //"HH:mm dd MMM"
            else -> "${day}.${month}.${year} ${hours}:${minutesString}:${secondsString}"
        }
    }

    fun stringToDate(data: String?): LocalDateTime? {
        var string = data?.replace("\"", "")
        return if (!string.isNullOrEmpty() && string != "null") {
            val position = string.lastIndexOf(".")
            if (position != -1) {
                string = "${string.substring(0, position).trim()}Z"
            }
            val instantBefore = Instant.parse(string)
            instantBefore.toLocalDateTime(TimeZone.UTC)
        } else null
    }

    fun birthdayStringToDateString(string: String?): String {
        return if (!string.isNullOrEmpty() && string != "null") {
            try {
                val date = stringToDate(string) ?: return ""
                val newDate = LocalDateTime(date.date, LocalTime(0, 0, 0))
                dateToString(newDate)
            } catch (e: Throwable) {
                ""
            }
        } else ""
    }

    fun stringToMessageTime(data: String?): String {
        var string = data?.replace("\"", "")
        return if (!string.isNullOrEmpty() && string != "null") {
            val position = string.lastIndexOf(".")
            if (position != -1) {
                string = "${string.substring(0, position).trim()}Z"
            }
            val instantBefore = Instant.parse(string)
            val localTime = instantBefore.toLocalDateTime(TimeZone.UTC)
            val hours = localTime.hour
            val minutes = localTime.minute


            val minutesString = if (minutes < 10) "0$minutes" else "$minutes"
            if (hours >= 12) {
                val newHoursValue = hours % 12
                val hoursString =
                    if (newHoursValue < 10) "0$newHoursValue" else "$newHoursValue"
                "${hoursString}:${minutesString}pm"
            } else {
                val hoursString = if (hours < 10) "0$hours" else "$hours"
                "${hoursString}:${minutesString}am"
            }
        } else ""
    }

    fun stringToOnlyDateString(data: String?): String {
        val date = stringToDate(data)
        val currentDate = getCurrentDate()
        val dateString = dateToString(date, shortDate)
        val currentDateString = dateToString(currentDate, shortDate)
        if (dateString == currentDateString) {
            return "Today"
        }
        val yesterdayDate = getYesterdayDate()
        val yesterdayDateString = dateToString(yesterdayDate, shortDate)
        if (dateString == yesterdayDateString) {
            return "Yesterday"
        }
        return dateString
    }

    fun dateToMillis(data: LocalDateTime? = null): Long {
        val currentMoment: Instant = Clock.System.now()
        val localTime = data ?: currentMoment.toLocalDateTime(TimeZone.currentSystemDefault())
        val instant = localTime.toInstant(TimeZone.currentSystemDefault())
        return instant.toEpochMilliseconds()
    }

    fun millisToDate(data: Long? = null): LocalDateTime {
        val instant = Instant.fromEpochMilliseconds(data ?: currentTimeMillis())
        return instant.toLocalDateTime(TimeZone.currentSystemDefault())
    }

    fun getCurrentDate(): LocalDateTime {
        val currentMoment: Instant = Clock.System.now()
        return currentMoment.toLocalDateTime(TimeZone.currentSystemDefault())
    }

    fun currentTimeMillis(): Long {
        val currentMoment: Instant = Clock.System.now()
        return currentMoment.toEpochMilliseconds()
    }

    fun getMonthName(month: Int): String {
        return when (month) {
            1 -> "Jan"
            2 -> "Feb"
            3 -> "Mar"
            4 -> "Apr"
            5 -> "May"
            6 -> "Jun"
            7 -> "Jul"
            8 -> "Aug"
            9 -> "Sep"
            10 -> "Oct"
            11 -> "Nov"
            12 -> "Dec"
            else -> ""
        }
    }

    fun getYesterdayDate(): LocalDateTime {
        val currentMoment: Instant = Clock.System.now()
        val yesterday =
            currentMoment.minus(1, DateTimeUnit.DAY, TimeZone.currentSystemDefault())
        return yesterday.toLocalDateTime(TimeZone.currentSystemDefault())
    }


    ///region Periods
    fun periodDifference(start: LocalDateTime, end: LocalDateTime): DatePeriod {
        val startDate = start.date
        val endDate = end.date
        val period = startDate.periodUntil(endDate)
        return period
    }

    fun timeDifference(
        start: LocalDateTime, end: LocalDateTime,
        timeZone: TimeZone = TimeZone.currentSystemDefault()
    ): TimeComponents { //Triple<Int, Int, Int> {
        val startInstant = start.toInstant(timeZone)
        val endInstant = end.toInstant(timeZone)

        val duration = endInstant - startInstant
        val totalSeconds = duration.inWholeSeconds

        val hours = (totalSeconds / 3600).toInt()
        val minutes = ((totalSeconds % 3600) / 60).toInt()
        val seconds = (totalSeconds % 60).toInt()

        /*val result = Triple(hours, minutes, seconds)
        result.first;  result.second ; result.third*/
        return TimeComponents(hours, minutes, seconds)
    }


    fun lessThanDays(string: String?, day: Int = 1, defaultValue: Boolean = true): Boolean {
        val date = stringToDate(string) ?: return defaultValue
        val days = (currentTimeMillis() - dateToMillis(date)) / (24 * 60 * 60 * 1000)
        return days < day
    }
    ///endregion
}

data class TimeComponents(val hours: Int, val minutes: Int, val seconds: Int)

