package network

import fiori.sharedmodule.generated.resources.Res
import fiori.sharedmodule.generated.resources.error_message_warning_title
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch
import kotpref.DelayedActionExecutor
import kotpref.eventBus.ClearDataEvent
import kotpref.eventBus.EventBusManager
import kotpref.logging.CommonLogger
import kotpref.models.EDialogType
import kotpref.models.UserAgent
import kotpref.stores.IAppKeysStorage
import kotpref.utils.IDialogManager
import kotpref.utils.INotificationManager
import kotpref.utils.IPlatformInfoManager
import kotpref.utils.PlatformType
import network.restApi.Endpoint
import network.restApi.NetworkSession
import network.socket.SocketEvent
import network.socket.SocketRequestsResponseManager
import network.socket.WebSocketManager
import ui.resources.ResManager


class RetrofitSession(
    val dialogManager: IDialogManager,
    val notificationsUtils: INotificationManager,
    val sessionEndpoint: Endpoint,
    val sessionAppKeys: IAppKeysStorage,
    val platformInfoManager: IPlatformInfoManager,
    val sessionLogger: CommonLogger,
    val sessionUserAgent: UserAgent
) : NetworkSession {

    private val TAG = "RetrofitSession"

    private var ktorSession: KtorSession
    private var webSocketClient: WebSocketManager

    init {
        val platformType = platformInfoManager.getPlatformType()
        val os = when (platformType) {
            PlatformType.iOS -> 1
            PlatformType.Android -> 2
            PlatformType.WebIOS -> 3
            PlatformType.WebAndroid -> 4
            PlatformType.WebMacBook -> 5
            PlatformType.Web -> 6
        }
        ktorSession = KtorSession(
            sessionEndpoint, sessionUserAgent.getUserAgent(),
            sessionUserAgent.deviceName, sessionAppKeys, notificationsUtils, sessionLogger, os = os,
            language = { platformInfoManager.getLanguage() },
            hasInternetConnection = { hasInternetConnection() })
        webSocketClient = ktorSession.webSocketClient
        dialogManager.setNetworkSession(this)
    }

    override fun ktorClient(): KtorSession {
        return ktorSession
    }

    override fun resetRetrofitClient() {
//        accountCallback()
    }

    override fun setAccountCallback(callback: (result: Any) -> Unit) {
        webSocketClient.socketRequestsResponseManager.accountCallback = callback
    }

    override fun hasInternetConnection(): Boolean {
        return platformInfoManager.hasInternetConnection()
    }

    override fun getAppKeys(): IAppKeysStorage = sessionAppKeys

    /*override fun getAccountApi(): AccountApi = ktorfitSession.getAccountApi()
    override fun getModerationApi(): ModerationApi = ktorfitSession.getModerationApi()
    override fun getSubscribeApi(): SubscribeApi = ktorfitSession.getSubscribeApi()

    //    override fun getStripeApi(): StripeApi = ktorfitSession.getStripeApi()
    override fun getChatApi(): ChatApi = ktorfitSession.getChatApi()
    override fun getFileApi(): FileApi = ktorfitSession.getFileApi()*/

    override fun getUserAgent(): UserAgent = sessionUserAgent
    override fun getLogger(): CommonLogger = sessionLogger

    override fun reconnectWebSocket(fromException: Boolean) {
        webSocketClient.reconnectWebSocket(fromException)
    }

    override fun webSocketSend(json: String?, event: String) {
        webSocketClient.webSocketSend(json, event)
    }

    override fun closeWebSocket(byInternetDisconnect: Boolean) {
        webSocketClient.closeWebSocket(byInternetDisconnect)
    }

    override fun socketRequestsResponseManager(): SocketRequestsResponseManager {
        return webSocketClient.socketRequestsResponseManager
    }

    override fun connectWebSocket(appVersion: String, firstConnect: Boolean) {
        webSocketClient.connectWebSocket(appVersion, firstConnect)
    }

    override fun readMessages(chatId: Int, messages: MutableList<String>) {
        webSocketClient.readMessages(chatId, messages)
    }

    override fun showMessage(
        message: String?, title: String, callback: () -> Unit, onCancel: () -> Unit,
        isLastDialog: Boolean
    ) {
        checkDialogNetworkSession()
        if (message == null) return
        DelayedActionExecutor({
            if (!message.contains("end of input at", true)) {
                CoroutineScope(Dispatchers.Main).launch {
                    val dialogTitle =
                        title.ifEmpty { ResManager.getString(Res.string.error_message_warning_title) }
                    dialogManager.showMessageWithTitleDialog(
                        dialogTitle, message, onCancel, isLastDialog = isLastDialog
                    )
                }
            }
        })
    }

    override fun showMessage(
        dialogType: EDialogType, callback: () -> Unit, onCancel: () -> Unit,
        title: String, dialogText: String, hint: String
    ) {
        checkDialogNetworkSession()
        DelayedActionExecutor({
            dialogManager.showMessageDialog(dialogType, callback, onCancel, title, dialogText, hint)
        })
    }

    override fun dismissMessage() {
        checkDialogNetworkSession()
        DelayedActionExecutor({
            dialogManager.dismissDialog()
        })
    }

    private fun checkDialogNetworkSession() {
        if (dialogManager.getNetworkSession() == null) {
            dialogManager.setNetworkSession(this)
        }
    }

    override fun clearData(reason: String) {
        EventBusManager.post(ClearDataEvent(reason))
    }

    override fun addChatRequestCallbacks(
        event: SocketEvent,
        onSuccess: (String?) -> Unit,
        onError: (String?) -> Unit
    ) {
        webSocketClient.addChatRequestCallbacks(event, onSuccess, onError)
    }
}