package web.screens.onboarding

import androidx.compose.runtime.Composable
import fiori.sharedmodule.generated.resources.Res
import fiori.sharedmodule.generated.resources.onboarding_compatibility_skip
import fiori.sharedmodule.generated.resources.onboarding_compatibility_text_answers
import fiori.sharedmodule.generated.resources.onboarding_compatibility_title
import ui.resources.ResManager
import ui.screens.onboarding.compatibility.OnBoardingCompatibilityEvent
import ui.screens.onboarding.compatibility.OnboardingCompatibilityVM
import web.helpers.rememberJsViewModel
import web.helpers.stringResource
import web.theme.JsMainTheme
import web.views.PageContainer
import web.views.LoadingState
import web.views.OnBoardingDefaultBox

@Composable
fun JsOnBoardingCompatibilityScreen(
    viewModelCallback: (OnBoardingCompatibilityEvent) -> Unit,
    viewModel: OnboardingCompatibilityVM = rememberJsViewModel {
        OnboardingCompatibilityVM(viewModelCallback)
    }
) {
    PageContainer {
        val text = viewModel.text.value
        if (text.isEmpty()) {
            LoadingState()
        } else OnBoardingDefaultBox(
            image = ResManager.drawable.bg_onboarding_compatibility,
            backButtonVisibility = viewModel.backButtonVisibility.value,
            title = stringResource(resource = Res.string.onboarding_compatibility_title),
            text = text,
            textColor = JsMainTheme.colors.text_color_gray,
            buttonText = viewModel.buttonText.value,
            compatibilityText = stringResource(resource = Res.string.onboarding_compatibility_text_answers),
            skipText = stringResource(resource = Res.string.onboarding_compatibility_skip),
            mainButtonClick = { viewModel.startCompatibility() },
            backButtonClick = { viewModel.back() },
            skipButtonClick = { viewModel.skipCompatibility() }
        )
    }
}
