package kotpref.models.typeConverter.multi

import kotpref.models.account.enums.AccountIam
import ui.resources.ResManager


/**
 * Created by Bohdan Shchavinskiy <bohdan@dream-tek.io> on 2019-04-16.
 */
class AccountIamConverter {
    companion object {

        fun listToPositions(list: MutableList<AccountIam>?): MutableList<Int>? {
            val positions = mutableListOf<Int>()
            list?.forEach { positions.add(it.position) }
            return positions
        }

        suspend fun stringToPositions(
            list: MutableList<String>?, myIdentity: Boolean = true
        ): MutableList<Int>? {
            val positions = mutableListOf<Int>()
            list?.forEach { item ->
                val element = AccountIam.sortList().firstOrNull {
                    val resId = ResManager.getString(it.resId())
                    val secondResId = ResManager.getString(it.secondResId())
                    (if (myIdentity) resId else secondResId) == item
                }
                if (element != null) positions.add(element.position)
            }
            return positions
        }

        fun positionsToList(positions: MutableList<Int>?): MutableList<AccountIam>? {
            if (positions == null) return null
            val list = mutableListOf<AccountIam>()
            if (positions.size != 0)
                positions.forEach { item ->
                    val element = AccountIam.sortList().firstOrNull { it.position == item }
                    if (element != null) list.add(element)
                }
            return list
        }


        fun getAccountGender(iam: MutableList<AccountIam>?): Int {
            if (iam == null || iam.size == 0) return -1
            var isMale = false
            var isFemale = false
            var isTrans = false
            var dontShow = false
            iam.forEach {
                when (it) {
                    /*AccountIam.T_W, AccountIam.M_C, AccountIam.M_B, AccountIam.M_G -> isMale = true
                    AccountIam.T_M, AccountIam.F_C, AccountIam.F_B, AccountIam.F_L -> isFemale =
                        true
                    AccountIam.T_0, AccountIam.T_1, AccountIam.T_2 -> isTrans =
                        true
                    AccountIam.T, AccountIam.C -> dontShow = true*/
                    else -> {}
                }
            }
            return when {
                dontShow -> -1
                isMale && !isFemale && !isTrans -> 0
                !isMale && isFemale && !isTrans -> 1
                isTrans -> 2
                else -> -1
            }
        }
    }
}