@Composable
fun JsOnBoardingTutorialScreen(
    fromFinishPage: Boolean,
    viewModelCallback: (OnBoardingTutorialEvent) -> Unit,
    viewModel: OnBoardingTutorialVM = rememberJsViewModel {
        OnBoardingTutorialVM(fromFinishPage, viewModelCallback)
    }
) {
    JsImagePreloaderQueue.addToQueue(
        listOf(
            Res.drawable.bg_onboarding_tutorial_second_page.getDrawableIdName(),
            Res.drawable.bg_onboarding_tutorial_third_page.getDrawableIdName(),

            Res.drawable.bg_onboarding_compatibility.getDrawableIdName(),
            Res.drawable.ic_compatibility_category_lifestyle.getDrawableIdName(),
            Res.drawable.ic_compatibility_category_sexual.getDrawableIdName(),
            Res.drawable.ic_compatibility_category_mindset.getDrawableIdName(),
            Res.drawable.ic_compatibility_category_goals.getDrawableIdName(),
            Res.drawable.ic_compatibility_category_habits.getDrawableIdName(),

            Res.drawable.bg_finish_page_with_compatibility.getDrawableIdName(),
            Res.drawable.bg_finish_page.getDrawableIdName(),

            Res.drawable.bg_propose_subscription_new.getDrawableIdName(),
            Res.drawable.bg_propose_subscription_middle_level.getDrawableIdName(),
            Res.drawable.ic_propose_subscription_logo_new.getDrawableIdName(),
            Res.drawable.bg_propose_subscribe_settings.getDrawableIdName(),
            Res.drawable.ic_subscribe_propose_have.getDrawableIdName(),
            Res.drawable.ic_subscribe_do_not_have.getDrawableIdName(),
        )
    )

    PageContainer {
        when (viewModel.currentQuestion.intValue) {
            0 -> OnBoardingTutorialFirstScreen()
            1 -> OnBoardingTutorialSecondScreen()
            2 -> OnBoardingTutorialThirdScreen()
        }

        Column(modifier = Modifier.fillMaxSize()) {
            Spacer(modifier = Modifier.fillMaxHeight(83.5.percent))

            MainButton(
                text = stringResource(resource = Res.string.onboarding_propose_subscription_continue),
                arrowIsVisible = true
            ) { viewModel.clickedBtn() }
        }
    }
}

const val ANIMATED_CONTENT_ANIMATION_DURATION = 300

@Composable
fun OnBoardingTutorialFirstScreen() {
    OnBoardingTutorialBox(
        image = Res.drawable.bg_onboarding_tutorial_first_page,
        text = stringResource(
            resource = Res.string.onboarding_tutorial_title_first_page, when {
                AppVariant.isElizium() -> "Elizium"
                AppVariant.isHeaven() -> "Heaven"
                AppVariant.isParadiz() -> "Paradiz"
                else -> "Fiorry"
            }
        )
    )
}

@Composable
fun OnBoardingTutorialSecondScreen() {
    OnBoardingTutorialBox(
        image = Res.drawable.bg_onboarding_tutorial_second_page,
        text = stringResource(resource = Res.string.onboarding_tutorial_title_second_page),
    )
}

@Composable
fun OnBoardingTutorialThirdScreen() {
    OnBoardingTutorialBox(
        image = Res.drawable.bg_onboarding_tutorial_third_page,
        text = onBoardingTutorialTitleThirdPage()
    )
}

@Composable
private fun onBoardingTutorialTitleThirdPage() =
    when {
        AppVariant.isElizium() -> stringResource(resource = Res.string.onboarding_tutorial_title_third_page_elizium)
        AppVariant.isHeaven() -> stringResource(resource = Res.string.onboarding_tutorial_title_third_page_heaven)
        AppVariant.isParadiz() -> stringResource(resource = Res.string.onboarding_tutorial_title_third_page_paradiz)
        else -> stringResource(resource = Res.string.onboarding_tutorial_title_third_page)
    }

@Composable
fun OnBoardingTutorialBox(
    image: DrawableResource,
    text: String,
    textColor: Color = JsMainTheme.colors.text_color_default,
    boxHeight: Float = 0.7f,
) {

    Box(Modifier.fillMaxSize()) {
        JsImageView(
            image,
            modifier = Modifier.fillMaxWidth(),
            contentScale = ContentScale.FillWidth
        )
    }

    Column(modifier = Modifier.fillMaxSize()) {
        Spacer(modifier = Modifier.fillMaxHeight(boxHeight.toPercent()))

        JsAutoResizeText(
            modifier = Modifier
                .fillMaxWidth(0.85f.toPercent())
                .align(Alignment.CenterHorizontally),
            text = text,
            color = textColor,
            fontWeight = FontWeight.Medium,
            maxTextSize = 18,
            textAlign = TextAlign.Center,
            maxLines = 4
        )
    }
}